// =====================================================================================
//  Custom.cs — مكان المبرمجين لأي ميزة جديدة
//  أي حاجة مش موجودة في قوائم Studio اكتبها هنا (أو في ملف جديد وناديه من هنا).
//
//  Install(h)       : بتتنادى أول ما اللعبة تفتح. هنا بتركّب ترقيعات Harmony.
//  OnGameReady(game): بتتنادى بعد ما الحملة تتحمّل.
//
//  مثال ترقيعة (شيل علامات // من قدام السطور عشان تشتغل):
//    var t = Reflect.FindType("TaleWorlds.CampaignSystem.Hero", "Hero");
//    var m = t.GetMethod("ChangeHeroGold");
//    h.Patch(m, prefix: new HarmonyMethod(typeof(Custom).GetMethod("GoldPrefix")));
//
//    public static void GoldPrefix(ref int __0) { if (__0 > 0) __0 = __0 * 2; }  // فلوس الضعف
//
//  نصايح:
//   - __0 و __1 ... معناها أول وتاني باراميتر في الدالة الأصلية. ref عشان تغيّر قيمته.
//   - return false في Prefix معناها "متكمّلش الدالة الأصلية".
//   - لو حصل خطأ اكتبه في Log.W وهتلاقيه في aurelion/aurelion.log جوه فولدر المود.
//   - أي تغيير في اللعب لازم يوصل لكل اللاعبين والسيرفر في نفس الوقت (Studio + Publisher بيعملوا كده).
// =====================================================================================
using HarmonyLib;
using TaleWorlds.Core;

namespace Aurelion.Core
{
    public static class Custom
    {
        public static void Install(Harmony h)
        {
        }

        public static void OnGameReady(Game game)
        {
        }
    }
}

