// =====================================================================================
//  PriceRules.cs — أسعار السوق
//  بعد ما الحملة تتحمّل، بنعدّي على كل حاجات اللعبة (أسلحة، دروع، خيل، بضايع...)
//  ونغيّر "القيمة الأساسية" بتاعتها بالنسبة اللي في prices.json.
//  أسعار المدن كلها بتتحسب من القيمة دي، فالتغيير بيوصل للسوق كله.
//  الترتيب: لو الحاجة ليها نسبة خاصة بيها تتطبّق هي، وإلا نسبة النوع بتاعها.
// =====================================================================================
using System;
using System.Collections.Generic;
using System.Reflection;
using TaleWorlds.Core;
using TaleWorlds.ObjectSystem;

namespace Aurelion.Core
{
    public static class PriceRules
    {
        static readonly Dictionary<string, int> original = new Dictionary<string, int>();

        public static void Apply()
        {
            if (Rules.TypePercent.Count == 0 && Rules.ItemPercent.Count == 0) return;
            if (MBObjectManager.Instance == null) return;
            var prop = typeof(ItemObject).GetProperty("Value", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            var setter = prop != null ? prop.GetSetMethod(true) : null;
            var field = typeof(ItemObject).GetField("<Value>k__BackingField", BindingFlags.Instance | BindingFlags.NonPublic);
            int changed = 0;
            foreach (var item in MBObjectManager.Instance.GetObjectTypeList<ItemObject>())
            {
                if (item == null || string.IsNullOrEmpty(item.StringId)) continue;
                double pct;
                if (!Rules.ItemPercent.TryGetValue(item.StringId, out pct) && !Rules.TypePercent.TryGetValue(item.ItemType.ToString(), out pct)) continue;
                int baseValue;
                if (!original.TryGetValue(item.StringId, out baseValue)) { baseValue = item.Value; original[item.StringId] = baseValue; }
                int v = Math.Max(1, (int)Math.Round(baseValue * pct / 100.0));
                if (v == item.Value) continue;
                if (setter != null) setter.Invoke(item, new object[] { v });
                else if (field != null) field.SetValue(item, v);
                else { Log.W("PriceRules: cannot write ItemObject.Value"); return; }
                changed++;
            }
            Log.W("PriceRules: changed " + changed + " item value(s)");
        }
    }
}

src.RenownRules.cs:
// =====================================================================================
//  RenownRules.cs — سرعة اكتساب الشهرة (renownMultiplier)
//  كل شهرة بتتكسب في اللعبة بتعدّي على GainRenownAction، فبنعترضها ونضرب الرقم.
//  مثال: 0.5 = الشهرة بتتكسب بنص السرعة.  2 = ضعف السرعة.
// =====================================================================================
using System;
using System.Reflection;
using HarmonyLib;

namespace Aurelion.Core
{
    public static class RenownRules
    {
        public static void Install(Harmony h)
        {
            var t = Reflect.FindType("TaleWorlds.CampaignSystem.Actions.GainRenownAction", "GainRenownAction");
            if (t == null) { Log.W("RenownRules: GainRenownAction not found"); return; }
            int n = 0;
            foreach (var m in t.GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))
            {
                var ps = m.GetParameters();
                if (m.Name == "ApplyInternal" && ps.Length >= 2 && ps[1].ParameterType == typeof(float))
                { h.Patch(m, prefix: new HarmonyMethod(typeof(RenownRules).GetMethod("Prefix", BindingFlags.Static | BindingFlags.Public))); n++; }
            }
            Log.W("RenownRules: patched " + n + " method(s)");
        }

        public static void Prefix(ref float __1)
        {
            if (__1 > 0 && Rules.RenownMultiplier != 1f) __1 *= Rules.RenownMultiplier;
        }
    }
}

src.Rules.cs:
// =====================================================================================
//  Rules.cs — بيقرا ملفات الإعدادات اللي Aurelion Studio بيكتبها:
//    aurelion/rules.json   : قواعد اللعب (حد المهارة، سرعة الخبرة، سرعة الشهرة)
//    aurelion/prices.json  : أسعار السوق (نسبة مئوية لكل نوع أو لكل حاجة)
//  متعدّلش الملفات دي بإيدك؛ عدّلها من Studio.
// =====================================================================================
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Reflection;
using System.Text;

namespace Aurelion.Core
{
    public static class Rules
    {
        public static string ModuleDir;
        public static string BuildVersion = "?";

        // Skill cap
        public static bool SkillCapEnabled;
        public static int SkillCapMax = 100;
        public static DateTime SkillCapFromUtc = DateTime.MinValue;
        public static DateTime SkillCapToUtc = DateTime.MinValue;

        // Multipliers (1.0 = بدون تغيير)
        public static float XpMultiplier = 1f;
        public static float RenownMultiplier = 1f;

        // Prices: percent (100 = بدون تغيير)
        public static Dictionary<string, double> TypePercent = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);
        public static Dictionary<string, double> ItemPercent = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase);

        public static bool SkillCapActiveNow
        {
            get
            {
                if (!SkillCapEnabled) return false;
                var now = DateTime.UtcNow;
                return now >= SkillCapFromUtc && now < SkillCapToUtc;
            }
        }

        public static void Load()
        {
            // <Module>\bin\Win64_Shipping_Client\Aurelion.Core.dll  ->  <Module>
            var dll = Assembly.GetExecutingAssembly().Location;
            ModuleDir = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(dll), "..", ".."));
            var dir = Path.Combine(ModuleDir, "aurelion");

            var r = ReadJson(Path.Combine(dir, "rules.json"));
            var b = ReadJson(Path.Combine(dir, "build.json"));
            BuildVersion = Mj.S(b, "version", "?");

            var sc = Mj.D(r, "skillCap");
            SkillCapEnabled = Mj.B(sc, "enabled", false);
            SkillCapMax = (int)Mj.N(sc, "max", 100);
            DateTime start;
            if (DateTime.TryParseExact(Mj.S(sc, "start", ""), "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal, out start))
            {
                // التاريخ بيتكتب بتوقيت القاهرة (UTC+2) في Studio
                SkillCapFromUtc = start.AddHours(-2);
                SkillCapToUtc = SkillCapFromUtc.AddDays(Math.Max(0, Mj.N(sc, "days", 7)));
            }
            XpMultiplier = (float)Mj.N(r, "xpMultiplier", 1);
            RenownMultiplier = (float)Mj.N(r, "renownMultiplier", 1);

            var p = ReadJson(Path.Combine(dir, "prices.json"));
            foreach (var kv in Mj.D(p, "types")) TypePercent[kv.Key] = Mj.ToD(kv.Value, 100);
            foreach (var kv in Mj.D(p, "items")) ItemPercent[kv.Key] = Mj.ToD(kv.Value, 100);

            Log.W("Rules: skillCap=" + SkillCapEnabled + " max=" + SkillCapMax + " " + SkillCapFromUtc.ToString("u") + " -> " + SkillCapToUtc.ToString("u")
                + " xp=" + XpMultiplier + " renown=" + RenownMultiplier + " priceTypes=" + TypePercent.Count + " priceItems=" + ItemPercent.Count);
        }

        static Dictionary<string, object> ReadJson(string path)
        {
            try { if (File.Exists(path)) return Mj.Parse(File.ReadAllText(path, Encoding.UTF8)) as Dictionary<string, object> ?? new Dictionary<string, object>(); }
            catch (Exception e) { Log.W("Could not read " + path + ": " + e.Message); }
            return new Dictionary<string, object>();
        }
    }

    // ---------------------------------------------------------------- tiny JSON reader
    public static class Mj
    {
        public static object Parse(string s) { int i = 0; var v = Val(s, ref i); return v; }

        static void Ws(string s, ref int i) { while (i < s.Length && char.IsWhiteSpace(s[i])) i++; }
        static object Val(string s, ref int i)
        {
            Ws(s, ref i);
            if (i >= s.Length) return null;
            char c = s[i];
            if (c == '{')
            {
                var d = new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase); i++;
                while (true)
                {
                    Ws(s, ref i); if (i < s.Length && s[i] == '}') { i++; break; }
                    var k = Str(s, ref i); Ws(s, ref i); i++; // :
                    d[k] = Val(s, ref i); Ws(s, ref i);
                    if (i < s.Length && s[i] == ',') { i++; continue; }
                    if (i < s.Length && s[i] == '}') { i++; break; }
                    throw new FormatException("bad object");
                }
                return d;
            }
            if (c == '[')
            {
                var l = new List<object>(); i++;
                while (true)
                {
                    Ws(s, ref i); if (i < s.Length && s[i] == ']') { i++; break; }
                    l.Add(Val(s, ref i)); Ws(s, ref i);
                    if (i < s.Length && s[i] == ',') { i++; continue; }
                    if (i < s.Length && s[i] == ']') { i++; break; }
                    throw new FormatException("bad array");
                }
                return l;
            }
            if (c == '"') return Str(s, ref i);
            if (s.Length - i >= 4 && s.Substring(i, 4) == "true") { i += 4; return true; }
            if (s.Length - i >= 5 && s.Substring(i, 5) == "false") { i += 5; return false; }
            if (s.Length - i >= 4 && s.Substring(i, 4) == "null") { i += 4; return null; }
            int st = i; while (i < s.Length && "+-0123456789.eE".IndexOf(s[i]) >= 0) i++;
            return double.Parse(s.Substring(st, i - st), CultureInfo.InvariantCulture);
        }
        static string Str(string s, ref int i)
        {
            var sb = new StringBuilder(); i++;
            while (i < s.Length && s[i] != '"')
            {
                if (s[i] == '\\')
                {
                    i++; char e = s[i];
                    if (e == 'n') sb.Append('\n'); else if (e == 't') sb.Append('\t'); else if (e == 'r') sb.Append('\r');
                    else if (e == 'u') { sb.Append((char)Convert.ToInt32(s.Substring(i + 1, 4), 16)); i += 4; }
                    else sb.Append(e);
                }
                else sb.Append(s[i]);
                i++;
            }
            i++; return sb.ToString();
        }

        public static Dictionary<string, object> D(Dictionary<string, object> d, string k)
        {
            object v; if (d != null && d.TryGetValue(k, out v) && v is Dictionary<string, object>) return (Dictionary<string, object>)v;
            return new Dictionary<string, object>();
        }
        public static string S(Dictionary<string, object> d, string k, string def) { object v; return d != null && d.TryGetValue(k, out v) && v != null ? Convert.ToString(v, CultureInfo.InvariantCulture) : def; }
        public static double N(Dictionary<string, object> d, string k, double def) { object v; return d != null && d.TryGetValue(k, out v) ? ToD(v, def) : def; }
        public static bool B(Dictionary<string, object> d, string k, bool def) { object v; return d != null && d.TryGetValue(k, out v) && v is bool ? (bool)v : def; }
        public static double ToD(object v, double def) { try { return v == null ? def : Convert.ToDouble(v, CultureInfo.InvariantCulture); } catch { return def; } }
    }

    // ---------------------------------------------------------------- log file: <Module>\aurelion\aurelion.log
    public static class Log
    {
        static string file;
        static readonly object lk = new object();
        public static void Start()
        {
            try
            {
                var dll = Assembly.GetExecutingAssembly().Location;
                var dir = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(dll), "..", "..", "aurelion"));
                Directory.CreateDirectory(dir);
                file = Path.Combine(dir, "aurelion.log");
                if (File.Exists(file) && new FileInfo(file).Length > 1024 * 1024) File.Delete(file);
            }
            catch { }
        }
        public static void W(string m)
        {
            try { lock (lk) if (file != null) File.AppendAllText(file, DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss") + "  " + m + Environment.NewLine); } catch { }
        }
    }
}

src.SkillRules.cs:
// =====================================================================================
//  SkillRules.cs — قواعد المهارات
//   1) حد أقصى للمهارة لفترة معينة (مثلاً 100 أول أسبوع من فتح السيرفر)
//   2) سرعة اكتساب الخبرة (xpMultiplier)
//  إزاي شغال؟ بنعترض دالتين في اللعبة (من غير ما نعدّل ملفاتها):
//   HeroDeveloper.AddSkillXp      : بتزوّد خبرة المهارة
//   HeroDeveloper.ChangeSkillLevel : بتغيّر مستوى المهارة
// =====================================================================================
using System;
using System.Reflection;
using HarmonyLib;

namespace Aurelion.Core
{
    public static class SkillRules
    {
        static PropertyInfo heroProp;      // HeroDeveloper.Hero
        static MethodInfo getSkillValue;   // Hero.GetSkillValue(SkillObject)

        public static void Install(Harmony h)
        {
            var dev = Reflect.FindType("TaleWorlds.CampaignSystem.CharacterDevelopment.HeroDeveloper", "HeroDeveloper");
            var hero = Reflect.FindType("TaleWorlds.CampaignSystem.Hero", "Hero");
            if (dev == null || hero == null) { Log.W("SkillRules: HeroDeveloper/Hero not found"); return; }
            heroProp = dev.GetProperty("Hero", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
            foreach (var m in hero.GetMethods(BindingFlags.Instance | BindingFlags.Public))
                if (m.Name == "GetSkillValue" && m.GetParameters().Length == 1) { getSkillValue = m; break; }

            int n = 0;
            foreach (var m in dev.GetMethods(BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.DeclaredOnly))
            {
                var ps = m.GetParameters();
                if (m.Name == "AddSkillXp" && ps.Length >= 2 && ps[1].ParameterType == typeof(float))
                { h.Patch(m, prefix: new HarmonyMethod(typeof(SkillRules).GetMethod("AddXpPrefix", BindingFlags.Static | BindingFlags.Public))); n++; }
                else if (m.Name == "ChangeSkillLevel" && ps.Length >= 2 && ps[1].ParameterType == typeof(int))
                { h.Patch(m, prefix: new HarmonyMethod(typeof(SkillRules).GetMethod("ChangeLevelPrefix", BindingFlags.Static | BindingFlags.Public))); n++; }
            }
            Log.W("SkillRules: patched " + n + " method(s)");
        }

        static int Level(object developer, object skill)
        {
            if (heroProp == null || getSkillValue == null || developer == null || skill == null) return -1;
            var hero = heroProp.GetValue(developer, null);
            if (hero == null) return -1;
            return (int)getSkillValue.Invoke(hero, new[] { skill });
        }

        // false = امنع اللعبة إنها تكمّل (مفيش خبرة)
        public static bool AddXpPrefix(object __instance, object __0, ref float __1)
        {
            try
            {
                if (__1 > 0 && Rules.XpMultiplier != 1f) __1 *= Rules.XpMultiplier;
                if (__1 > 0 && Rules.SkillCapActiveNow && Level(__instance, __0) >= Rules.SkillCapMax) return false;
            }
            catch (Exception e) { Log.W("AddXpPrefix: " + e.Message); }
            return true;
        }

        public static bool ChangeLevelPrefix(object __instance, object __0, ref int __1)
        {
            try
            {
                if (__1 > 0 && Rules.SkillCapActiveNow)
                {
                    var lvl = Level(__instance, __0);
                    if (lvl >= 0 && lvl + __1 > Rules.SkillCapMax)
                    {
                        __1 = Rules.SkillCapMax - lvl;
                        if (__1 <= 0) return false;
                    }
                }
            }
            catch (Exception e) { Log.W("ChangeLevelPrefix: " + e.Message); }
            return true;
        }
    }

    public static class Reflect
    {
        public static Type FindType(string fullName, string shortName)
        {
            var t = AccessTools.TypeByName(fullName);
            if (t != null) return t;
            foreach (var a in AppDomain.CurrentDomain.GetAssemblies())
            {
                if (!a.GetName().Name.StartsWith("TaleWorlds", StringComparison.OrdinalIgnoreCase)) continue;
                Type[] ts;
                try { ts = a.GetTypes(); } catch (ReflectionTypeLoadException e) { ts = e.Types; }
                foreach (var x in ts) if (x != null && x.Name == shortName) return x;
            }
            return null;
        }
    }
}

src.SubModule.cs:
// =====================================================================================
//  Aurelion.Core  —  الكود بتاعنا جوه مود Coop (على السيرفر وعند اللاعيبة)
//  ده "باب الدخول" للمود. اللعبة بتنادي الدوال اللي هنا لوحدها.
//  - OnSubModuleLoad : أول ما اللعبة تفتح  -> بنقرا الإعدادات ونركّب الترقيعات (Harmony)
//  - OnGameInitializationFinished : بعد ما الحملة تتحمّل -> بنطبّق أسعار السوق
//  - OnApplicationTick : كل فريم -> نظام إدارة اللاعبين (على السيرفر بس)
//  قواعد اللعب مش بتشتغل غير لما تتفعّل من صفحة "قواعد اللعب" (RulesGate).
//  لو هتضيف ميزة جديدة: اعمل ملف جديد في فولدر src، وناديه من هنا (شوف Custom.cs).
//  [AdminHost] — العلامة دي بيستخدمها الاستوديو عشان يعرف إن الملف ده الإصدار الجديد.
// =====================================================================================
using System;
using HarmonyLib;
using TaleWorlds.Core;
using TaleWorlds.MountAndBlade;

namespace Aurelion.Core
{
    public class SubModule : MBSubModuleBase
    {
        public static Harmony H;
        static bool rulesOn;

        protected override void OnSubModuleLoad()
        {
            base.OnSubModuleLoad();
            try
            {
                Log.Start();
                Rules.Load();
                H = new Harmony("aurelion.core");
                rulesOn = RulesGate.Enabled;
                if (rulesOn) { SkillRules.Install(H); RenownRules.Install(H); }
                else Log.W("Rules are OFF (enable them from the Studio rules page)");
                Custom.Install(H);
                AdminHost.Start(H);
                Log.W("Aurelion.Core " + Rules.BuildVersion + " loaded");
            }
            catch (Exception e) { Log.W("OnSubModuleLoad failed: " + e); }
        }

        public override void OnGameInitializationFinished(Game game)
        {
            base.OnGameInitializationFinished(game);
            try { if (rulesOn) PriceRules.Apply(); Custom.OnGameReady(game); }
            catch (Exception e) { Log.W("OnGameInitializationFinished failed: " + e); }
        }

        protected override void OnApplicationTick(float dt)
        {
            base.OnApplicationTick(dt);
            AdminHost.Tick();
        }
    }
}

src.system/AdminClient.cs:
// =====================================================================================
//  system/AdminClient.cs — لوحة الإدارة جوه اللعبة (على جهاز الأدمن)  — v14 (التصميم المعتمد)
//  ملف نظام: الاستوديو بيكتبه من جديد مع كل بناء. متعدّلش فيه — أي تعديل هيتمسح.
//
//  F10 أو !menu في الشات ← اللوحة بتسأل السيرفر "أنا أدمن؟" ← السيرفر بيبعت الصلاحيات واللاعيبة.
//  كل زرار بيبعت للسيرفر "!ui do <أمر>" والسيرفر بيتأكد من الصلاحية قبل ما ينفّذ.
//  الرسايل دي مش بتظهر في الشات لحد (لا عند الأدمن ولا عند غيره).
//  الشكل في GUI\Prefabs\AurelionAdmin.xml والألوان في GUI\Brushes\AurelionAdmin.xml (هوية أوريليون).
// =====================================================================================
using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using HarmonyLib;
using TaleWorlds.Library;
using TaleWorlds.InputSystem;
using TaleWorlds.ScreenSystem;
using TaleWorlds.Engine.GauntletUI;

namespace Aurelion.Core
{
    public static class AdminClient
    {
        const string Marker = "\u0001AUR|";
        static Harmony harmony;
        static bool patched; static int patchTries;
        static object network; static MethodInfo sendAll; static ConstructorInfo msgCtor; static object globalChannel;
        static object chatService; static PropertyInfo isTyping;
        static object menu;            // AdminMenu (kept as object so the server never loads the UI types)
        static AdminMenuVM vm;
        static DateTime nextPatch = DateTime.MinValue, waitingSince = DateTime.MinValue;
        static int errors;

        public static void Start(Harmony h) { harmony = h; }

        public static void Tick()
        {
            try
            {
                if (!patched && DateTime.UtcNow >= nextPatch) { nextPatch = DateTime.UtcNow.AddSeconds(3); TryPatch(); }
                if (Input.InputManager == null) return;   // dedicated server: no keyboard
                if (menu != null) ((AdminMenu)menu).TickMenu();
                if (Input.IsKeyPressed(InputKey.F10) && Input.IsKeyDown(InputKey.LeftControl) && Input.IsKeyDown(InputKey.LeftShift) && PreviewAllowed())
                {
                    if (menu != null) Close(); else OpenPreview();
                }
                else if (Input.IsKeyPressed(InputKey.F10) && !Typing())
                {
                    if (menu != null) Close();
                    else Request();
                }
                if (waitingSince != DateTime.MinValue && (DateTime.UtcNow - waitingSince).TotalSeconds > 8)
                { waitingSince = DateTime.MinValue; Toast("السيرفر مردّش. اتأكد إنك داخل السيرفر.", false); }
                errors = 0;
            }
            catch (Exception e)
            {
                if (++errors <= 5) Log.W("AdminClient.Tick: " + e);
                if (errors > 50) throw;
            }
        }

        static void TryPatch()
        {
            if (++patchTries > 400) { patched = true; return; }
            var cs = AccessTools.TypeByName("GameInterface.Services.Chat.ChatService");
            var m = cs == null ? null : AccessTools.Method(cs, "Receive");
            if (m == null || harmony == null) return;
            harmony.Patch(m, new HarmonyMethod(typeof(AdminClient).GetMethod("ReceivePrefix", BindingFlags.Static | BindingFlags.Public)));
            patched = true;
            Log.W("AdminClient: menu channel ready (F10)");
        }

        static bool Typing()
        {
            try
            {
                if (chatService == null) chatService = AdminHost.Resolve("GameInterface.Services.Chat.IChatService");
                if (chatService == null) return false;
                if (isTyping == null) isTyping = chatService.GetType().GetProperty("IsTyping");
                return isTyping != null && isTyping.GetValue(chatService, null) is bool && (bool)isTyping.GetValue(chatService, null);
            }
            catch { return false; }
        }

