        public static bool Send(string line)
        {
            if (Preview) return true;
            try
            {
                if (network == null) network = AdminHost.Resolve("Common.Network.INetwork");
                if (network == null) { Toast("مش متوصل بالسيرفر.", false); return false; }
                if (sendAll == null)
                {
                    var it = AccessTools.TypeByName("Common.Network.INetwork");
                    sendAll = it.GetMethods().First(x => x.Name == "SendAll" && x.GetParameters().Length == 1 && x.GetParameters()[0].ParameterType.Name == "IMessage");
                    var mt = AccessTools.TypeByName("GameInterface.Services.Chat.Messages.NetworkSendChatMessage");
                    msgCtor = mt.GetConstructors().First(c => c.GetParameters().Length == 3);
                    globalChannel = Enum.Parse(msgCtor.GetParameters()[0].ParameterType, "Global");
                }
                sendAll.Invoke(network, new object[] { msgCtor.Invoke(new object[] { globalChannel, null, line }) });
                return true;
            }
            catch (Exception e) { Log.W("AdminClient.Send: " + (e.InnerException ?? e).Message); Toast("مقدرتش أبعت للسيرفر.", false); return false; }
        }

