        public static bool ReceivePrefix(object[] __args)
        {
            try
            {
                if (__args == null || __args.Length < 1) return true;
                var f = __args[0].GetType().GetField("Text");
                var text = f == null ? null : f.GetValue(__args[0]) as string;
                if (text == null || !text.StartsWith(Marker, StringComparison.Ordinal)) return true;
                var rest = text.Substring(Marker.Length);
                var bar = rest.IndexOf('|');
                var kind = bar < 0 ? rest : rest.Substring(0, bar);
                var json = bar < 0 ? "{}" : rest.Substring(bar + 1);
                Handle(kind, Mj.Parse(json) as Dictionary<string, object> ?? new Dictionary<string, object>());
                return false;   // menu traffic never shows in the chat
            }
            catch (Exception e) { Log.W("AdminClient.Receive: " + e); return false; }
        }

        static void Handle(string kind, Dictionary<string, object> d)
        {
            switch (kind)
            {
                case "denied":
                    waitingSince = DateTime.MinValue;
                    Toast("لوحة الإدارة للأدمنز بس.", false);
                    break;
                case "hello":
                    waitingSince = DateTime.MinValue;
                    if (vm == null) vm = new AdminMenuVM();
                    vm.LoadHello(d);
                    if (menu == null) { var m = new AdminMenu(vm); m.Open(); menu = m; }
                    break;
                case "pin":
                    waitingSince = DateTime.MinValue;
                    if (vm == null) vm = new AdminMenuVM();
                    vm.ShowPin(Mj.S(d, "name", ""), Mj.S(d, "error", ""), Mj.S(d, "locked", ""));
                    if (menu == null) { var m = new AdminMenu(vm); m.Open(); menu = m; }
                    break;
                case "players": if (vm != null) vm.LoadPlayers(d); break;
                case "result": if (vm != null) vm.ShowResultU(Mj.B(d, "ok", false), Mj.S(d, "text", ""), Mj.B(d, "undo", false)); else Toast(Mj.S(d, "text", ""), Mj.B(d, "ok", false)); break;
                case "alerts": if (vm != null) vm.LoadAlerts(d); break;
                case "health": if (vm != null) vm.LoadHealth(d); break;
                case "banner": ShowBanner(Mj.S(d, "text", ""), Mj.S(d, "by", "")); break;
                case "bans": if (vm != null) vm.LoadBans(d); break;
                case "log": if (vm != null) vm.LoadLog(d); break;
                case "world": if (vm != null) vm.LoadWorldPart(d); break;
            }
        }

