        // an announcement from the admins in the middle of every player's screen (the game's big notice), plus a gold line in the messages
        public static void ShowBanner(string text, string by)
        {
            if ((text ?? "").Trim().Length == 0) return;
            try
            {
                var tt = AccessTools.TypeByName("TaleWorlds.Localization.TextObject");
                var ctor = tt.GetConstructors().FirstOrDefault(c => c.GetParameters().Length >= 1 && c.GetParameters()[0].ParameterType == typeof(string));
                var ps = ctor.GetParameters(); var args = new object[ps.Length]; args[0] = "إعلان من الإدارة:  " + text;
                for (int i = 1; i < ps.Length; i++) args[i] = ps[i].HasDefaultValue ? ps[i].DefaultValue : null;
                var to = ctor.Invoke(args);
                var mi = AccessTools.TypeByName("TaleWorlds.Core.MBInformationManager");
                var m = mi == null ? null : mi.GetMethods(BindingFlags.Static | BindingFlags.Public).FirstOrDefault(x => x.Name == "AddQuickInformation" && x.GetParameters().Length >= 1 && x.GetParameters()[0].ParameterType == tt);
                if (m != null)
                {
                    var mp = m.GetParameters(); var a2 = new object[mp.Length]; a2[0] = to;
                    for (int i = 1; i < mp.Length; i++) a2[i] = mp[i].HasDefaultValue ? mp[i].DefaultValue : (mp[i].ParameterType.IsValueType ? Activator.CreateInstance(mp[i].ParameterType) : null);
                    if (mp.Length > 1 && mp[1].ParameterType == typeof(int)) a2[1] = 6000;   // stays a few seconds longer
                    m.Invoke(null, a2);
                }
            }
            catch (Exception e) { Log.W("AdminClient.Banner: " + (e.InnerException ?? e).Message); }
            try { InformationManager.DisplayMessage(new InformationMessage("[إعلان من الإدارة]  " + text, Color.FromUint(0xFFE8B94E))); } catch { }
        }

