    // ---------------------------------------------------------------- Aurelion skin: custom images inside the game UI (all reflection, never throws)
    // The image lives as a loose PNG in <module>\GUI\SpriteSheets\<file>; its sprite/part definitions are in GUI\Sprites\AurelionSpriteData.xml.
    // EnsureSprite() hands the PNG to the game's sprite category, and returns false (caller keeps the plain background) if anything is off.
    public static class AurelionSkin
    {
        static readonly Dictionary<string, int> fails = new Dictionary<string, int>(); public static string Status = "";
        static void Fail(string category) { int n; fails.TryGetValue(category, out n); fails[category] = n + 1; }
        const BindingFlags All = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Instance | BindingFlags.Static;

        static Type T(string name) { foreach (var a in AppDomain.CurrentDomain.GetAssemblies()) { try { var t = a.GetType(name, false); if (t != null) return t; } catch { } } return null; }
        static object Static(Type t, string prop) { var p = t.GetProperty(prop, All); if (p != null) return p.GetValue(null, null); var f = t.GetField(prop, All); return f != null ? f.GetValue(null) : null; }
        static object Get(object o, string prop) { var p = o.GetType().GetProperty(prop, All); if (p != null) return p.GetValue(o, null); var f = o.GetType().GetField(prop, All); return f != null ? f.GetValue(o) : null; }

        static void Note(string s) { Status = s; try { Aurelion.Core.Log.W("Skin: " + s); } catch { } }

        static string Sig(MethodInfo m) { return m.Name + "(" + string.Join(", ", m.GetParameters().Select(x => x.ParameterType.Name).ToArray()) + ")"; }
        static bool Alive(object tex)
        {
            if (tex == null) return false;
            try { var v = Get(tex, "IsValid"); if (v is bool) return (bool)v; } catch { }
            return true;
        }

        // The engine's texture factory changed between game versions, so every overload is tried with arguments built from its parameter types.
        static object MakeEngineTexture(string dir, string file, string moduleName)
        {
            var tt = T("TaleWorlds.Engine.Texture");
            if (tt == null) { Note("Texture type missing"); return null; }
            var full = Path.Combine(dir, file);
            var rel1 = "../../Modules/" + moduleName + "/GUI/SpriteSheets/"; var rel2 = "Modules/" + moduleName + "/GUI/SpriteSheets/";
            var dirSep = dir + Path.DirectorySeparatorChar;
            var names = new[] { "CreateTextureFromPath", "LoadTextureFromPath", "CreateFromByteArray", "CreateFromMemory" };
            foreach (var m in tt.GetMethods(All)) if (m.IsStatic && names.Contains(m.Name)) Note("overload " + Sig(m));

            // easiest route: hand the PNG file bytes to the engine
            try
            {
                var bytes = File.ReadAllBytes(full);
                foreach (var m in tt.GetMethods(All))
                {
                    if (!m.IsStatic || m.Name != "CreateFromMemory") continue;
                    var ps0 = m.GetParameters();
                    if (ps0.Length < 1 || ps0[0].ParameterType != typeof(byte[])) continue;
                    var a0 = new object[ps0.Length]; a0[0] = bytes;
                    for (int i = 1; i < ps0.Length; i++) a0[i] = ps0[i].HasDefaultValue ? ps0[i].DefaultValue : (ps0[i].ParameterType.IsValueType ? Activator.CreateInstance(ps0[i].ParameterType) : null);
                    try { var r0 = m.Invoke(null, a0); Note("CreateFromMemory returned " + (r0 == null ? "null" : r0.GetType().Name + " valid=" + Alive(r0))); if (Alive(r0)) { Note("texture via " + Sig(m)); return r0; } } catch (Exception e0) { Note("memory try failed: " + (e0.InnerException ?? e0).Message); }
                }
            }
            catch (Exception e1) { Note("memory route failed: " + e1.Message); }

            foreach (var m in tt.GetMethods(All))
            {
                if (!m.IsStatic || m.Name != "CreateTextureFromPath") continue;
                var ps = m.GetParameters();
                var tries = new List<object[]>();
                if (ps.Length == 2 && ps[0].ParameterType == typeof(string) && ps[1].ParameterType == typeof(string))
                { tries.Add(new object[] { dirSep, file }); tries.Add(new object[] { rel1, file }); tries.Add(new object[] { rel2, file }); tries.Add(new object[] { dir, file }); }
                else if (ps.Length == 1 && ps[0].ParameterType == typeof(string)) { tries.Add(new object[] { full }); tries.Add(new object[] { rel1 + file }); }
                else if (ps.Length >= 1 && ps[0].ParameterType.Name == "PlatformFilePath")
                {
                    var fpT = ps[0].ParameterType; var dpT = T("TaleWorlds.Library.PlatformDirectoryPath"); var ftT = T("TaleWorlds.Library.PlatformFileType");
                    if (dpT != null && ftT != null)
                        foreach (var ft in Enum.GetValues(ftT))
                            foreach (var d in new[] { dir, rel1, rel2 })
                            {
                                try
                                {
                                    var dp = Activator.CreateInstance(dpT, new object[] { ft, d });
                                    var fp = Activator.CreateInstance(fpT, new object[] { dp, file });
                                    var args = new object[ps.Length]; args[0] = fp;
                                    for (int i = 1; i < ps.Length; i++) args[i] = ps[i].HasDefaultValue ? ps[i].DefaultValue : (ps[i].ParameterType.IsValueType ? Activator.CreateInstance(ps[i].ParameterType) : null);
                                    tries.Add(args);
                                } catch (Exception ec) { Note("path ctor failed: " + (ec.InnerException ?? ec).Message); }
                            }
                }
                foreach (var a in tries)
                {
                    try { var r = m.Invoke(null, a); if (Alive(r)) { Note("texture via " + Sig(m)); return r; } else Note("path route gave an invalid texture"); } catch (Exception e) { Note("try failed: " + (e.InnerException ?? e).Message); }
                }
            }
            // fallback: decode the PNG ourselves and hand raw pixels to the engine
            try
            {
                System.Reflection.Assembly drawing = null; try { drawing = System.Reflection.Assembly.Load("System.Drawing, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b03f5f7f11d50a3a"); } catch { }
                var bmpT = drawing == null ? null : drawing.GetType("System.Drawing.Bitmap"); var rectT = drawing == null ? null : drawing.GetType("System.Drawing.Rectangle");
                if (bmpT == null || rectT == null) { Note("System.Drawing missing"); return null; }
                var bmp = Activator.CreateInstance(bmpT, new object[] { full });
                int w = (int)Get(bmp, "Width"), h = (int)Get(bmp, "Height");
                var rect = Activator.CreateInstance(rectT, new object[] { 0, 0, w, h });
                var lb = bmpT.GetMethods().First(x => x.Name == "LockBits" && x.GetParameters().Length == 3 && x.GetParameters()[1].ParameterType.IsEnum && x.GetParameters()[2].ParameterType.IsEnum);
                var bd = lb.Invoke(bmp, new object[] { rect, Enum.ToObject(lb.GetParameters()[1].ParameterType, 1), Enum.ToObject(lb.GetParameters()[2].ParameterType, 2498570) });
                var scan0 = (IntPtr)Get(bd, "Scan0"); int stride = (int)Get(bd, "Stride");
                var buf = new byte[w * h * 4];
                for (int y = 0; y < h; y++) System.Runtime.InteropServices.Marshal.Copy(new IntPtr(scan0.ToInt64() + (long)y * stride), buf, y * w * 4, w * 4);
                bmpT.GetMethod("UnlockBits").Invoke(bmp, new object[] { bd });
                for (int i = 0; i < buf.Length; i += 4) { var b0 = buf[i]; buf[i] = buf[i + 2]; buf[i + 2] = b0; }   // BGRA -> RGBA
                foreach (var m in tt.GetMethods(All))
                {
                    if (!m.IsStatic || m.Name != "CreateFromByteArray") continue;
                    var ps = m.GetParameters();
                    if (ps.Length < 3 || ps[0].ParameterType != typeof(byte[])) continue;
                    var args = new object[ps.Length]; args[0] = buf; args[1] = w; args[2] = h;
                    for (int i = 3; i < ps.Length; i++) args[i] = ps[i].HasDefaultValue ? ps[i].DefaultValue : (ps[i].ParameterType.IsValueType ? Activator.CreateInstance(ps[i].ParameterType) : null);
                    try { var r = m.Invoke(null, args); if (Alive(r)) { Note("texture via raw pixels " + Sig(m)); return r; } } catch (Exception e) { Note("raw try failed: " + (e.InnerException ?? e).Message); }
                }
            }
            catch (Exception e) { Note("raw fallback failed: " + (e.InnerException ?? e).Message); }
            return null;
        }

        public static bool EnsureSprite(string category, string pngFile)
        {
            int failed; if (fails.TryGetValue(category, out failed) && failed >= 3) return false;
            try
            {
                var uiRes = T("TaleWorlds.Engine.GauntletUI.UIResourceManager");
                if (uiRes == null) { Fail(category); Note("UIResourceManager missing"); return false; }
                var sd = Static(uiRes, "SpriteData");
                if (sd == null) { Fail(category); Note("SpriteData null"); return false; }
                var cats = Get(sd, "SpriteCategories") as IDictionary;
                if (cats == null) { Fail(category); Note("categories null"); return false; }

                // if the game did not pick up our sprite xml by itself, load it ourselves and copy it in
                if (!cats.Contains(category))
                {
                    var sdType = sd.GetType();
                    var mine = Activator.CreateInstance(sdType, new object[] { "AurelionSpriteData" });
                    var depot = Static(uiRes, "UIResourceDepot");
                    var lm = sdType.GetMethod("LoadFromDepot", All);
                    if (lm == null || depot == null) { Fail(category); Note("cannot load sprite xml"); return false; }
                    lm.Invoke(mine, new object[] { depot });
                    foreach (var prop in new[] { "SpriteCategories", "SpriteParts", "Sprites" })
                    {
                        var src = Get(mine, prop) as IDictionary; var dst = Get(sd, prop) as IDictionary;
                        if (src == null || dst == null) continue;
                        foreach (DictionaryEntry de in src) dst[de.Key] = de.Value;
                    }
                    cats = Get(sd, "SpriteCategories") as IDictionary;
                    if (!cats.Contains(category)) { Fail(category); Note("category not found in xml"); return false; }
                }

                var cat = cats[category];
                var sheets = Get(cat, "SpriteSheets") as IList;
                if (sheets == null) { Fail(category); Note("no sheets list"); return false; }
                if (sheets.Count > 0)
                {   // already injected: make sure the texture is still alive
                    try { var tex0 = sheets[0]; var valid = Get(tex0, "IsValid"); if (valid is bool && (bool)valid) return true; } catch { }
                    sheets.Clear();
                }

                var asmPath = typeof(AurelionSkin).Assembly.Location;
                var module = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(asmPath), "..", ".."));
                var dir = Path.Combine(module, "GUI", "SpriteSheets");
                if (!File.Exists(Path.Combine(dir, pngFile))) { Fail(category); Note("image missing: " + pngFile); return false; }

                var eng = MakeEngineTexture(dir, pngFile, Path.GetFileName(module));
                if (eng == null) { Fail(category); Note("texture could not be created"); return false; }

                try { var keep = eng.GetType().GetMethod("SetTextureAsAlwaysValid", All); if (keep != null) keep.Invoke(eng, null); } catch { }
                // every texture needs its own name: the engine keeps one image material per texture name, so nameless textures end up drawing each other
                try { var np = eng.GetType().GetProperty("Name", All); if (np != null && np.CanWrite) np.SetValue(eng, "aurelion_" + category, null); Note("name " + (np == null ? "?" : Convert.ToString(np.GetValue(eng, null)))); } catch (Exception en) { Note("name failed: " + (en.InnerException ?? en).Message); }
                var wrapType = T("TaleWorlds.Engine.GauntletUI.EngineTexture");
                var twoDType = T("TaleWorlds.TwoDimension.Texture");
                if (wrapType == null || twoDType == null) { Fail(category); Note("texture types missing"); return false; }
                var wrap = Activator.CreateInstance(wrapType, new object[] { eng });
                var tex = Activator.CreateInstance(twoDType, new object[] { wrap });
                sheets.Add(tex);
                var isLoaded = cat.GetType().GetProperty("IsLoaded", All);
                if (isLoaded != null) isLoaded.SetValue(cat, true, null);
                Note("ok " + category);
                return true;
            }
            catch (Exception e) { Fail(category); Note("failed: " + (e.InnerException != null ? e.InnerException.Message : e.Message)); return false; }
        }
    }

