    // ---------------------------------------------------------------- Aurelion's own font (Cairo): atlases in GUI\SpriteSheets, metrics in GUI\AurelionFont
    // Registered the same way the Arabic mod registers its font (sprite named like the font + FontFactory.TryAddFontDefinition),
    // then every Aur.* brush is pointed at it. Runs before each time the menu opens (cheap when everything is already in place).
    public static class AurFont
    {
        static int tries;
        static readonly string[] Names = { "Aurelion-Regular", "Aurelion-SemiBold", "Aurelion-Bold" };
        static readonly string[] Cats = { "aur_font_regular", "aur_font_semibold", "aur_font_bold" };
        static readonly string[] SemiBrushes = { "Aur.Blue", "Aur.Accent", "Aur.Red", "Aur.BrandSmall", "Aur.BtnText", "Aur.TabText", "Aur.Chip", "Aur.PinError", "Aur.RowTitle" };
        static readonly string[] BoldBrushes = { "Aur.Gold", "Aur.Brand", "Aur.BrandC", "Aur.Caption", "Aur.PinTitle", "Aur.DialogTitle", "Aur.PinInput" };
        public static bool Ready;

        public static void Ensure()
        {
            Ready = false;
            if (tries >= 3) return;
            for (int i = 0; i < Cats.Length; i++)
                if (!AurelionSkin.EnsureSprite(Cats[i], Cats[i] + "_1.png")) { tries++; Log.W("Font: atlas not loaded: " + Cats[i]); return; }
            var ff = TaleWorlds.Engine.GauntletUI.UIResourceManager.FontFactory; var sd = TaleWorlds.Engine.GauntletUI.UIResourceManager.SpriteData;
            var bf = TaleWorlds.Engine.GauntletUI.UIResourceManager.BrushFactory;
            if (ff == null || sd == null || bf == null) { tries++; Log.W("Font: factory missing"); return; }
            var module = Path.GetFullPath(Path.Combine(Path.GetDirectoryName(typeof(AurFont).Assembly.Location), "..", ".."));
            var dir = Path.Combine(module, "GUI", "AurelionFont");
            var fonts = new TaleWorlds.TwoDimension.Font[Names.Length];
            for (int i = 0; i < Names.Length; i++)
            {
                fonts[i] = Add(ff, sd, dir, Names[i]);
                if (fonts[i] == null) { tries++; Log.W("Font: could not register " + Names[i]); return; }
            }
            int n = 0;
            foreach (var br in bf.Brushes)
            {
                if (br == null || br.Name == null || !br.Name.StartsWith("Aur.", StringComparison.Ordinal)) continue;
                // v14 brushes say their weight in the name: ".B" = Bold, ".S" = SemiBold
                var f = fonts[2];   // every Aurelion line in the bold cut: the thinner cuts looked faint in the game (sizes and colours keep the hierarchy)
                if (br.Font == f) { n++; continue; }
                br.Font = f;
                foreach (var st in br.Styles) st.Font = f;
                n++;
            }
            Ready = true;
            if (!logged) { logged = true; Log.W("Font: Aurelion fonts ready (" + n + " brushes, sprite=" + (fonts[0].FontSprite != null) + ", chars=" + fonts[0].CharacterCount + ")"); }
        }
        static bool logged;

        static TaleWorlds.TwoDimension.Font Find(TaleWorlds.GauntletUI.FontFactory ff, string name)
        {
            foreach (var f in ff.GetFonts()) if (f != null && f.Name == name) return f;
            return null;
        }

        static TaleWorlds.TwoDimension.Font Add(TaleWorlds.GauntletUI.FontFactory ff, TaleWorlds.TwoDimension.SpriteData sd, string dir, string name)
        {
            var have = Find(ff, name);
            if (have != null) return have;
            if (!File.Exists(Path.Combine(dir, name + ".fnt"))) { Log.W("Font: file missing " + name + ".fnt"); return null; }
            foreach (var p in new[] { dir.Replace('\\', '/') + "/", dir + Path.DirectorySeparatorChar })
            {
                try { var ok = ff.TryAddFontDefinition(p, name, sd); Log.W("Font: TryAddFontDefinition(" + name + ") = " + ok); } catch (Exception e) { Log.W("Font: add failed: " + (e.InnerException ?? e).Message); }
                have = Find(ff, name);
                if (have != null) return have;
            }
            return null;
        }
    }

    // ---------------------------------------------------------------- motion (same numbers as the launcher): fade + slide in, slow zoom on the picture, breathing glows
    public class AurAnim
    {
        class Tw { public TaleWorlds.GauntletUI.BaseTypes.Widget W; public double Start, Dur; public float Dy; public bool Fade; public List<TaleWorlds.GauntletUI.BaseTypes.Widget> All; }
        const float BgW = 1422f, BgH = 800f;
        readonly TaleWorlds.GauntletUI.BaseTypes.Widget root; readonly AdminMenuVM vm;
        readonly TaleWorlds.GauntletUI.BaseTypes.Widget bg;
        readonly List<TaleWorlds.GauntletUI.BaseTypes.Widget> halos = new List<TaleWorlds.GauntletUI.BaseTypes.Widget>();
        readonly List<TaleWorlds.GauntletUI.BaseTypes.Widget> pulses = new List<TaleWorlds.GauntletUI.BaseTypes.Widget>();
        readonly List<TaleWorlds.GauntletUI.BaseTypes.Widget> dots = new List<TaleWorlds.GauntletUI.BaseTypes.Widget>();
        readonly List<Tw> tweens = new List<Tw>();
        DateTime last = DateTime.UtcNow; double t;
        string lastTab = null; bool lastConfirm, lastPin; int lastSerial; bool fadeOk = true; int lastCat; bool lastPalette, lastToast;

        static bool Live(string id) { return id == "AurGlow" || id == "AurLogoGlow" || id == "AurDotGlow"; }

        public AurAnim(GauntletLayer layer, object movie, AdminMenuVM vm)
        {
            this.vm = vm;
            TaleWorlds.GauntletUI.BaseTypes.Widget r = null;
            try
            {
                var mp = movie.GetType().GetProperty("Movie"); var mv = mp == null ? movie : mp.GetValue(movie, null);
                var rp = mv == null ? null : mv.GetType().GetProperty("RootWidget");
                if (rp != null) r = rp.GetValue(mv, null) as TaleWorlds.GauntletUI.BaseTypes.Widget;
            }
            catch { }
            if (r == null) r = layer.UIContext.Root;
            root = r;
            bg = Find("AurHero");
            foreach (var w in root.GetAllChildrenAndThisRecursive())
            {
                if (w.Id == "AurGlow") pulses.Add(w);
                else if (w.Id == "AurLogoGlow") halos.Add(w);
                else if (w.Id == "AurDotGlow") dots.Add(w);
            }
            lastTab = vm.CurTab; lastConfirm = vm.HasConfirm; lastPin = vm.IsPinScreen; lastSerial = vm.ResultSerial;
            Enter(Find("AurWin"), 0, 12f, true, 0.30);
            Log.W("Anim: ready (bg=" + (bg != null) + " halos=" + halos.Count + " pulses=" + pulses.Count + ")");
        }

        TaleWorlds.GauntletUI.BaseTypes.Widget Find(string id) { return root.FindChild(id, true); }

        void Enter(TaleWorlds.GauntletUI.BaseTypes.Widget w, double delay, float dy, bool fade, double dur)
        {
            if (w == null) return;
            tweens.RemoveAll(x => x.W == w);
            var tw = new Tw { W = w, Start = t + delay, Dur = dur, Dy = dy, Fade = fade && fadeOk };
            if (tw.Fade) tw.All = w.GetAllChildrenAndThisRecursive();
            tweens.Add(tw);
            Apply(tw, 0f);
        }

        void Apply(Tw tw, float e)
        {
            tw.W.PositionYOffset = tw.Dy * (1f - e);
            if (!tw.Fade || tw.All == null) return;
            try
            {
                for (int i = 0; i < tw.All.Count; i++)
                {
                    var w = tw.All[i];
                    if (Live(w.Id)) continue;
                    w.AlphaFactor = e;
                    var bw = w as TaleWorlds.GauntletUI.BaseTypes.BrushWidget;
                    if (bw != null) bw.Brush.GlobalAlphaFactor = e;
                }
            }
            catch (Exception ex) { fadeOk = false; tw.Fade = false; Log.W("Anim: fade off: " + ex.Message); }
        }

        static float Wave(double t, double period, double lo, double hi) { return (float)(lo + (hi - lo) * (0.5 - 0.5 * Math.Cos(2 * Math.PI * t / period))); }

        public void Tick()
        {
            var now = DateTime.UtcNow; var dt = (now - last).TotalSeconds; last = now;
            if (dt < 0) dt = 0; if (dt > 0.1) dt = 0.1;
            t += dt;

            // what changed since the last frame
            if (vm.CurTab != lastTab)
            {
                lastTab = vm.CurTab; Enter(Find("AurPage_" + lastTab), 0, 14f, false, 0.40);
                for (int i = 1; i <= 6; i++) Enter(Find("AurPage_" + lastTab + "_" + i), 0.05 * (i - 1), 14f, true, 0.42);   // cards come in one after the other
            }
            if (vm.CatSerial != lastCat) { lastCat = vm.CatSerial; Enter(Find("AurActs"), 0, 10f, true, 0.30); }
            if (vm.HasPalette != lastPalette) { lastPalette = vm.HasPalette; if (lastPalette) Enter(Find("AurPaletteCard"), 0, 10f, true, 0.24); }
            if (vm.HasToast != lastToast) { lastToast = vm.HasToast; if (lastToast) Enter(Find("AurToast"), 0, 16f, true, 0.32); }
            if (vm.HasConfirm != lastConfirm) { lastConfirm = vm.HasConfirm; if (lastConfirm) Enter(Find("AurConfirmCard"), 0, 10f, true, 0.24); }
            if (vm.IsPinScreen != lastPin)
            {
                lastPin = vm.IsPinScreen;
                if (lastPin) Enter(Find("AurPin"), 0, 14f, true, 0.40);
                else { Enter(Find("AurPage"), 0, 14f, true, 0.40); Enter(Find("AurHeader"), 0.04, -8f, true, 0.36); }
            }
            if (vm.ResultSerial != lastSerial) { lastSerial = vm.ResultSerial; Enter(Find("AurToast"), 0, 16f, true, 0.32); Enter(Find("AurBar"), 0, 0f, true, 1.2); }

            for (int i = tweens.Count - 1; i >= 0; i--)
            {
                var tw = tweens[i];
                var p = (t - tw.Start) / tw.Dur;
                if (p < 0) continue;
                if (p >= 1) { Apply(tw, 1f); tweens.RemoveAt(i); continue; }
                var q = 1.0 - p; Apply(tw, (float)(1.0 - q * q * q));
            }

            if (bg != null)
            {   // slow zoom in and out: 1.0 -> 1.07 in 28 seconds, like the launcher's main picture
                var s = 1.0 + 0.07 * (0.5 - 0.5 * Math.Cos(2 * Math.PI * t / 56.0));
                bg.SuggestedWidth = (float)(BgW * s); bg.SuggestedHeight = (float)(BgH * s);
            }
            var ha = Wave(t, 5.2, 0.15, 0.60); for (int i = 0; i < halos.Count; i++) halos[i].AlphaFactor = ha;      // logo glow: 2.6 s each way
            var pa = Wave(t, 3.2, 0.35, 0.95); for (int i = 0; i < pulses.Count; i++) pulses[i].AlphaFactor = pa;   // primary button glow: 1.6 s each way
            var da = Wave(t, 2.2, 0.25, 0.90); for (int i = 0; i < dots.Count; i++) dots[i].AlphaFactor = da;       // online dot
        }
    }

