        public class WSet { public string Id, Type, Name, Owner, Kingdom, KingdomId, Bound; }
        public class WKing { public string Id, Name, Leader, LeaderId; public int Towns, Castles, Villages, Clans; }

        static object Pv(object o, string n)
        {
            if (o == null) return null;
            var t = o as Type ?? o.GetType(); var fl = BindingFlags.Public | BindingFlags.NonPublic | (o is Type ? BindingFlags.Static : BindingFlags.Instance);
            for (var c = t; c != null; c = c.BaseType)
            {
                var p = c.GetProperty(n, fl | BindingFlags.DeclaredOnly); if (p != null && p.GetIndexParameters().Length == 0) return p.GetValue(o is Type ? null : o, null);
                var f = c.GetField(n, fl | BindingFlags.DeclaredOnly); if (f != null) return f.GetValue(o is Type ? null : o);
            }
            return null;
        }
        static string Sv(object o) { return o == null ? "" : o.ToString(); }
        static bool Bv(object o, string n) { var v = Pv(o, n); return v is bool && (bool)v; }

        // reads the world from the admin's own copy of the campaign: names come out in the game's language and nothing big goes over the chat
        void LoadWorld()
        {
            var sets = new List<WSet>(); var kings = new List<WKing>();
            try
            {
                var st = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Settlements.Settlement");
                var all = Pv(st, "All") as IEnumerable;
                if (all != null)
                    foreach (var s in all)
                    {
                        bool town = Bv(s, "IsTown"), castle = Bv(s, "IsCastle"), village = Bv(s, "IsVillage");
                        if (!town && !castle && !village) continue;
                        var oc = Pv(s, "OwnerClan"); var k = oc == null ? null : Pv(oc, "Kingdom");
                        var w = new WSet { Id = Sv(Pv(s, "StringId")), Name = Sv(Pv(s, "Name")), Type = town ? "town" : castle ? "castle" : "village",
                                           Owner = oc == null ? "" : Sv(Pv(oc, "Name")), Kingdom = k == null ? "" : Sv(Pv(k, "Name")), KingdomId = k == null ? "" : Sv(Pv(k, "StringId")) };
                        if (village) { var vc = Pv(s, "Village"); var b = vc == null ? null : Pv(vc, "Bound"); w.Bound = b == null ? "" : Sv(Pv(b, "Name")); }
                        if (w.Id.Length > 0) sets.Add(w);
                    }
                var kt = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Kingdom");
                var ka = Pv(kt, "All") as IEnumerable;
                if (ka != null)
                    foreach (var k in ka)
                    {
                        if (Bv(k, "IsEliminated")) continue;
                        var ld = Pv(k, "Leader"); var cl = Pv(k, "Clans") as IEnumerable;
                        kings.Add(new WKing { Id = Sv(Pv(k, "StringId")), Name = Sv(Pv(k, "Name")), Leader = ld == null ? "" : Sv(Pv(ld, "Name")), LeaderId = ld == null ? "" : Sv(Pv(ld, "StringId")),
                                              Clans = cl == null ? 0 : cl.Cast<object>().Count() });
                    }
            }
            catch (Exception e) { Log.W("AdminMenu.LoadWorld: " + (e.InnerException ?? e).Message); }

            if (kings.Count == 0)   // fall back to the server's list
                kings = kingdoms.Select(x => new WKing { Id = Mj.S(x, "id", ""), Name = Mj.S(x, "name", ""), Leader = Mj.S(x, "leader", ""), LeaderId = Mj.S(x, "leaderId", ""), Clans = (int)Mj.N(x, "clans", 0) }).ToList();
            if (sets.Count == 0)
            {
                sets = serverSets.ToList();
                if (sets.Count == 0 && !worldAsked) { worldAsked = true; AdminClient.Send("!ui world"); }
            }
            foreach (var k in kings)
            {
                k.Towns = sets.Count(x => x.KingdomId == k.Id && x.Type == "town");
                k.Castles = sets.Count(x => x.KingdomId == k.Id && x.Type == "castle");
                k.Villages = sets.Count(x => x.KingdomId == k.Id && x.Type == "village");
            }
            wsets = sets.OrderBy(x => x.Type == "town" ? 0 : x.Type == "castle" ? 1 : 2).ThenBy(x => x.Name, StringComparer.CurrentCultureIgnoreCase).ToList();
            wkings = kings.OrderByDescending(x => x.Towns + x.Castles).ThenBy(x => x.Name, StringComparer.CurrentCultureIgnoreCase).ToList();
            RefreshWorld(); RefreshKings(); RefreshWorldTarget(); FilterSettlements();
        }

        public void LoadWorldPart(Dictionary<string, object> d)
        {
            if ((int)Mj.N(d, "part", 0) == 0) serverSets.Clear();
            foreach (var it in L(d, "items").Select(x => Convert.ToString(x)))
            {
                var f = it.Split('\t'); if (f.Length < 6) continue;
                serverSets.Add(new WSet { Id = f[0], Type = f[1], Name = f[2], Owner = f[3], Kingdom = f[4], KingdomId = f[5], Bound = "" });
            }
            if ((int)Mj.N(d, "part", 0) + 1 >= (int)Mj.N(d, "parts", 1)) LoadWorld();
        }

