        void RefreshWorld()
        {
            var q = (WorldSearch ?? "").Trim();
            var list = wsets.Where(x => (wType == "all" || x.Type == wType) && (q.Length == 0 || x.Name.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0
                                        || x.Owner.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0 || x.Kingdom.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)).ToList();
            var pages = Math.Max(1, (list.Count + WPage - 1) / WPage);
            if (wPage >= pages) wPage = pages - 1; if (wPage < 0) wPage = 0;
            WorldSettlements.Clear();
            foreach (var x in list.Skip(wPage * WPage).Take(WPage))
            {
                var sub = TypeAr(x.Type) + "  •  " + (x.Owner.Length > 0 ? x.Owner : "من غير صاحب") + (x.Kingdom.Length > 0 ? "  •  " + x.Kingdom : "");
                var row = new AdminRowVM(x.Id, x.Name, sub, r => { selSet = r.Key; RefreshWorld(); }, null, null);
                row.IsSelected = x.Id == selSet; WorldSettlements.Add(row);
            }
            WorldPageText = (wPage + 1) + " / " + pages;
            WorldHeader = "المدن والقلاع والقرى  (" + list.Count + (list.Count != wsets.Count ? " من " + wsets.Count : "") + ")";
            HasNoWorld = list.Count == 0;
            WAll = wType == "all"; WTown = wType == "town"; WCastle = wType == "castle"; WVillage = wType == "village";
            var s = SelSet;
            SelSetText = s == null ? "اختار مستوطنة من القايمة" : TypeAr(s.Type) + " " + s.Name + "  —  صاحبها: " + (s.Owner.Length > 0 ? s.Owner : "مفيش") + (s.Kingdom.Length > 0 ? "  •  " + s.Kingdom : "") + (s.Type == "village" && (s.Bound ?? "").Length > 0 ? "  •  تبع " + s.Bound : "");
            IsSelVillage = s != null && s.Type == "village";
            RefreshW14();
        }
