        // ------------------------------------------------ troops of a chosen type (from the admin's own campaign)
        public class WTroop { public string Id, Name, Culture, CultureId, Kind; public int Tier; }
        List<WTroop> troops = new List<WTroop>(); List<string[]> cultures = new List<string[]>();
        int cultureIdx, tierSel, troopPage; string selTroop = "";
        const int TPage = 12, IPage = 12;
        static readonly HashSet<string> TroopOcc = new HashSet<string> { "Soldier", "Mercenary", "Bandit", "Gangster", "Guard", "CaravanGuard", "Outlaw", "Deserter" };

        void LoadTroops()
        {
            var list = new List<WTroop>();
            try
            {
                var ct = AccessTools.TypeByName("TaleWorlds.CampaignSystem.CharacterObject");
                var all = Pv(ct, "All") as IEnumerable;
                if (all != null)
                    foreach (var c in all)
                    {
                        if (Bv(c, "IsHero")) continue;
                        var occ = Sv(Pv(c, "Occupation"));
                        if (occ.Length > 0 && !TroopOcc.Contains(occ)) continue;
                        var cul = Pv(c, "Culture");
                        int tier = 0; try { tier = Convert.ToInt32(Pv(c, "Tier")); } catch { }
                        if (tier < 1) continue;
                        var id = Sv(Pv(c, "StringId")); var name = Sv(Pv(c, "Name"));
                        if (id.Length == 0 || name.Length == 0 || id.StartsWith("_") || id.Contains("template") || id.Contains("tutorial")) continue;
                        var kind = Bv(c, "IsMounted") ? (Bv(c, "IsRanged") ? "فارس رامي" : "فارس") : (Bv(c, "IsRanged") ? "رامي" : "مشاة");
                        list.Add(new WTroop { Id = id, Name = name, Tier = tier, Culture = cul == null ? "من غير ثقافة" : Sv(Pv(cul, "Name")), CultureId = cul == null ? "none" : Sv(Pv(cul, "StringId")), Kind = kind });
                    }
            }
            catch (Exception e) { Log.W("AdminMenu.LoadTroops: " + (e.InnerException ?? e).Message); }
            troops = list.OrderBy(x => x.Culture).ThenBy(x => x.Tier).ThenBy(x => x.Name).ToList();
            cultures = new List<string[]> { new[] { "", "كل الثقافات" } };
            cultures.AddRange(troops.GroupBy(x => x.CultureId).Select(g => new[] { g.Key, g.First().Culture }).OrderBy(x => x[1]));
            RefreshTroops();
        }
        void RefreshTroops()
        {
            if (cultures.Count == 0) cultures.Add(new[] { "", "كل الثقافات" });
            cultureIdx = (cultureIdx % cultures.Count + cultures.Count) % cultures.Count;
            tierSel = (tierSel % 7 + 7) % 7;
            CultureName = cultures[cultureIdx][1]; TierText = tierSel == 0 ? "الكل" : "مستوى " + tierSel;
            var q = (TroopSearch ?? "").Trim(); var cid = cultures[cultureIdx][0];
            var list = troops.Where(x => (cid.Length == 0 || x.CultureId == cid) && (tierSel == 0 || x.Tier == tierSel) && (q.Length == 0 || x.Name.IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0)).ToList();
            var pages = Math.Max(1, (list.Count + TPage - 1) / TPage);
            if (troopPage >= pages) troopPage = pages - 1; if (troopPage < 0) troopPage = 0;
            TroopMatches.Clear();
            foreach (var t in list.Skip(troopPage * TPage).Take(TPage))
            {
                var row = new AdminRowVM(t.Id, t.Name, "مستوى " + t.Tier + "  •  " + t.Kind + "  •  " + t.Culture, r => { selTroop = r.Key; RefreshTroops(); }, null, null);
                row.IsSelected = t.Id == selTroop; TroopMatches.Add(row);
            }
            TroopPageText = (troopPage + 1) + " / " + pages + (list.Count > 0 ? "  (" + list.Count + ")" : "");
            var s = troops.FirstOrDefault(x => x.Id == selTroop);
            SelTroopText = s == null ? (troops.Count == 0 ? "مش قادر أقرا أنواع الجنود من الحملة" : "اختار نوع جندي من القايمة") : s.Name + "  —  مستوى " + s.Tier + "  •  " + s.Kind + "  •  " + s.Culture;
        }
        public void ExecuteCulturePrev() { cultureIdx--; troopPage = 0; RefreshTroops(); }
        public void ExecuteCultureNext() { cultureIdx++; troopPage = 0; RefreshTroops(); }
        public void ExecuteTierPrev() { tierSel--; troopPage = 0; RefreshTroops(); }
        public void ExecuteTierNext() { tierSel++; troopPage = 0; RefreshTroops(); }
        public void ExecuteTroopPrev() { troopPage--; RefreshTroops(); }
        public void ExecuteTroopNext() { troopPage++; RefreshTroops(); }
        int CountFrom(string text, int max)
        {
            int n; if (!int.TryParse((text ?? "").Trim().Replace(",", ""), NumberStyles.Integer, CultureInfo.InvariantCulture, out n) || n < 1) { ShowResult(false, "اكتب العدد (رقم من 1 لـ " + max + ")"); return 0; }
            if (n > max) { ShowResult(false, "أقصى عدد في المرة " + max); return 0; }
            return n;
        }
