        // ------------------------------------------------ helpers
        static IEnumerable<object> L(Dictionary<string, object> d, string k) { object v; return d != null && d.TryGetValue(k, out v) && v is IEnumerable && !(v is string) ? ((IEnumerable)v).Cast<object>() : Enumerable.Empty<object>(); }
        static string N(Dictionary<string, object> p, string k) { return Mj.N(p, k, 0).ToString("N0", CultureInfo.InvariantCulture); }
        static string PName(Dictionary<string, object> p) { var h = Mj.S(p, "heroName", ""); var s = Mj.S(p, "platformName", ""); return h.Length > 0 ? h + (s.Length > 0 && s != h ? "  (" + s + ")" : "") : s; }
        static string Cut(string s, int n) { s = s ?? ""; return s.Length > n ? s.Substring(0, n) + "…" : s; }
        static string ActionAr(string a)
        {
            switch (a)
            {
                case "join": return "دخل"; case "leave": return "خرج"; case "kick": return "طرد"; case "ban": return "حظر"; case "unban": return "فك حظر";
                case "server-start": return "السيرفر اشتغل";
            }
            if (a.StartsWith("chat:")) return "!" + a.Substring(5);
            if (a.StartsWith("run:")) return a.Substring(4);
            if (a.StartsWith("denied:")) return "اتمنع !" + a.Substring(7);
            return a;
        }

