        // grids fill left to right; each row is reversed so the first item sits on the right (Arabic reading order)
        static void AddRtl(MBBindingList<AurVM> list, List<AurVM> items, int cols)
        {
            list.Clear();
            for (int i = 0; i < items.Count; i += cols)
            {
                var row = items.Skip(i).Take(cols).ToList(); row.Reverse();
                foreach (var x in row) list.Add(x);
            }
        }
        static string Hm(string iso) { return iso.Length >= 16 ? (iso.Substring(0, 10) == DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) ? iso.Substring(11, 5) : iso.Substring(8, 2) + "/" + iso.Substring(5, 2) + " " + iso.Substring(11, 5)) : iso; }

