        void RefreshFeed()
        {
            PAlerts.Clear(); Feed.Clear();
            var p = Sel;
            if (p != null)
            {
                foreach (var a in alertsAll.Where(x => Mj.S(x, "target", "") == selCid && !ignoredAlerts.Contains(AlertKey(x))).Take(3))
                {
                    var key = AlertKey(a);
                    PAlerts.Add(new AurVM(key, Mj.S(a, "title", ""), null).WithSub(Cut(Mj.S(a, "text", ""), 110)).WithTime(Hm(Mj.S(a, "time", "")))
                        .WithA("راجع", r => SetTab("alerts")).WithB("تجاهل", r => { ignoredAlerts.Add(r.Key); RefreshFeed(); RefreshAlerts(); RefreshP14(); }));
                }
                var name = Hero(p);
                var items = new List<KeyValuePair<string, AurVM>>();
                foreach (var l in logAll.Where(x => Mj.S(x, "target", "") == selCid || (Mj.S(x, "targetName", "").Length > 0 && Mj.S(x, "targetName", "").StartsWith(name))).Take(12))
                {
                    var okL = Mj.B(l, "ok", false); var act = Mj.S(l, "action", "");
                    var txt = (act == "join" ? "دخل السيرفر" : act == "leave" ? "خرج من السيرفر" : Mj.S(l, "byName", "") + ": " + CmdAr(act, Mj.S(l, "reason", ""))) + (okL ? "" : " (ما اتنفذش)");
                    items.Add(new KeyValuePair<string, AurVM>(Mj.S(l, "time", ""), new AurVM("", txt, null).WithTime(Hm(Mj.S(l, "time", ""))).State(okL && act.StartsWith("chat:"), false, !okL)));
                }
                foreach (var a in alertsAll.Where(x => Mj.S(x, "target", "") == selCid).Take(6))
                    items.Add(new KeyValuePair<string, AurVM>(Mj.S(a, "time", ""), new AurVM("", "تنبيه: " + Mj.S(a, "title", ""), null).WithTime(Hm(Mj.S(a, "time", ""))).State(false, true, false)));
                foreach (var it in items.OrderByDescending(x => x.Key).Take(12)) Feed.Add(it.Value);
            }
            HasPAlerts = PAlerts.Count > 0; HasNoFeed = Feed.Count == 0;
        }

        // command names in Arabic for the log and the feed
        static string CmdAr(string action, string line)
        {
            var name = action.StartsWith("chat:") ? action.Substring(5) : action;
            var tk = (line ?? "").Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            Func<int, string> arg = i => tk.Length > i ? tk[i] : "";
            switch (name)
            {
                case "gold": return "فلوس " + arg(2);
                case "renown": return "شهرة " + arg(2);
                case "influence": return "نفوذ " + arg(2);
                case "skill": return "مهارة " + arg(2) + " = " + arg(3);
                case "skillreset": return "ريست المهارات";
                case "attr": return "نقط صفات +" + arg(2);
                case "focus": return "نقط تركيز +" + arg(2);
                case "troops": return "ضيف جنود";
                case "troopsclear": return "مسح الجنود";
