                case "itemset": return "حاجات " + arg(3);
                case "prisoners": return "ضيف أسرى";
                case "prisonersclear": return "مسح الأسرى";
                case "starter": return "باقة لاعب جديد";
                case "kick": return "طرد";
                case "ban": return "حظر نهائي";
                case "tban": return "حظر " + arg(2) + " ساعة";
                case "banid": return "حظر برقم Steam";
                case "unban": return "فك حظر";
                case "warn": return "تحذير";
                case "mute": return "كتم " + (arg(2) == "0" ? "دايم" : arg(2) + " دقيقة");
                case "unmute": return "فك الكتم";
                case "pm": return "رسالة خاصة";
                case "say": return "إعلان شات";
                case "banner": return "إعلان بانر";
                case "adminsay": return "رسالة للإدارة";
                case "sched": return "إعلان مجدول";
                case "unsched": return "إلغاء إعلان مجدول";
                case "unstuck": return "فك العلقة";
                case "free": return "فك الأسر";
                case "tp": return "نقل لمدينة";
                case "goto": return "راح له";
                case "bring": return "جابه عنده";
                case "give": return "ادّاله مدينة";
                case "take": return "سحب مدينة";
                case "kingdom": return "دخّله مملكة";
                case "vassal": return "خلّاه تابع";
                case "leave": return "خروج من المملكة (" + LeaveAr(arg(2)) + ")";
                case "kwar": return "حرب بين مملكتين";
                case "kpeace": return "سلام بين مملكتين";
                case "note": return "ملاحظة";
                case "undo": return "تراجع";
                case "restart": return "ريستارت بعد " + arg(1) + " دقيقة";
                case "save": return "حفظ الحملة";
