        // ---- watch a player: the admin's own map camera follows his army (local only, nothing is sent, he doesn't know)
        static string watching = "";
        void Watch()
        {
            try
            {
                var mpT = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Party.MobileParty");
                object party = null;
                if (watching.Length > 0) { party = Pv(mpT, "MainParty"); watching = ""; }
                else
                {
                    var p = Sel; var pid = p == null ? "" : Mj.S(p, "partyId", "");
                    var all = Pv(mpT, "All") as IEnumerable;
                    if (all != null && pid.Length > 0) foreach (var x in all) if (Sv(Pv(x, "StringId")) == pid) { party = x; break; }
                    if (party == null) { ShowResult(false, "مش لاقي جيشه على الخريطة (لازم تكون جوه الحملة وهو يكون على الخريطة)."); return; }
                    watching = Hero(p);
                }
                var pb = Pv(party, "Party");
                var m = pb == null ? null : pb.GetType().GetMethod("SetAsCameraFollowParty", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic);
                if (m == null) { watching = ""; ShowResult(false, "اللعبة مش بتسمح بتحريك الكاميرا هنا."); return; }
                m.Invoke(pb, null);
                RefreshCats();
                if (watching.Length > 0) { AdminClient.Close(); AdminClient.Toast("بتراقب " + watching + " — افتح F10 ودوس «وقّف المراقبة» عشان ترجع لجيشك", true); }
                else ShowResult(true, "الكاميرا رجعت لجيشك");
            }
            catch (Exception e) { watching = ""; ShowResult(false, "المراقبة مش متاحة: " + (e.InnerException ?? e).Message); }
        }
        void Leave(string mode)
        {
            var p = Sel; if (p == null) return;
            if (Mj.S(p, "kingdom", "").Length == 0) { ShowResult(false, Hero(p) + " مش في مملكة."); return; }
            var k = Mj.S(p, "kingdom", "");
            string d;
            if (mode == "keep") d = "هيخرج من " + k + " ومعاه كل مدنه وقلاعه، وهيبقى في سلام مع كل الممالك (حتى " + k + "). النتيجة الحقيقية هتوصلك بعد ثواني.";
            else if (mode == "war") d = "هيخرج من " + k + " بإقطاعاته، ويبقى في حرب مع " + k + " بس وسلام مع كل الباقي.";
            else if (mode == "allwar") d = "هيخرج من " + k + " بإقطاعاته، ويبقى في حرب مع كل الممالك.";
            else if (mode == "bare") d = "هيخرج من " + k + " وإقطاعاته ترجع لحاكمها، ويبقى في سلام مع الكل.";
            else d = "هيخرج من " + k + " زي اللعبة العادية: إقطاعاته بترجع للمملكة.";
            Danger("خروج من المملكة — " + LeaveAr(mode), d, false, (r, h) => AdminClient.Do("leave " + Target + " " + mode));
        }

        void RefreshCats()
        {
            if (Cats == null) return;
            var acts = AllActs();
            if (!acts.Any(a => a.Cat == cat && a.Allowed)) { var f = CatDefs.FirstOrDefault(c => acts.Any(a => a.Cat == c[0] && a.Allowed)); if (f != null) cat = f[0]; }
            Cats.Clear();
            foreach (var c in CatDefs.Reverse())   // the strip is drawn left to right: last first, so the first category ends on the right
            {
                if (!acts.Any(a => a.Cat == c[0] && a.Allowed)) continue;
                var cc = c[0];
                var row = new AurVM(cc, c[1], r => { cat = r.Key; form = ""; CatSerial++; RefreshCats(); RefreshForm(); });
                row.IsSelected = cc == cat; Cats.Add(row);
            }
            var def = CatDefs.FirstOrDefault(c => c[0] == cat);
            CatHint = def == null ? "" : def[2];
            Acts.Clear();
            var mine = acts.Where(a => a.Cat == cat && a.Allowed).ToList();
            // the grid fills left to right: each row of three is reversed so the first command sits top-right
            for (int i = 0; i < mine.Count; i += 3)
            {
                var rowActs = mine.Skip(i).Take(3).ToList();
                while (rowActs.Count < 3) rowActs.Add(null);
                rowActs.Reverse();
                foreach (var a in rowActs)
                {
                    if (a == null) { Acts.Add(new AurVM("", "", null).Flags(false, false).WithIcon("")); continue; }
                    var run = a.Run;
                    Acts.Add(new AurVM(a.Key, a.Label, r => { if (Sel == null) { ShowResult(false, "اختار لاعب الأول"); return; } run(); }).WithSub(a.Desc).WithIcon(a.Icon).Flags(a.Danger, a.IsNew).State(true, false, false));
                }
            }
        }

