        void RefreshForm()
        {
            IsGrid = form.Length == 0; OnPropertyChanged("HasForm");
            FGold = form == "gold"; FRes = form == "res"; FSkill = form == "skill"; FTroops = form == "troops"; FItems = form == "items"; FTp = form == "tp";
            FKingdom = form == "kingdom"; FMute = form == "mute"; FMsg = form == "warn" || form == "pm"; FNote = form == "note"; FOwned = form == "owned"; FPris = form == "pris"; FAttr = form == "attr";
            var who = SelHero.Length > 0 ? " — " + SelHero : "";
            switch (form)
            {
                case "gold": FormTitle = "الفلوس" + who; break;
                case "res": FormTitle = (resKind == "renown" ? "الشهرة" : "النفوذ") + who; ResText = resKind == "renown" ? "شهرة" : "نفوذ"; break;
                case "skill": FormTitle = "المهارات" + who; break;
                case "troops": FormTitle = "ضيف / شيل جنود" + who; break;
                case "items": FormTitle = "حاجات في الشنطة" + who; break;
                case "tp": FormTitle = "انقله لمدينة" + who; break;
                case "kingdom": { FormTitle = (kKind == "join" ? "دخّله مملكة" : "خلّيه تابع لمملكة") + who; KFormBtn = kKind == "join" ? "دخّله المملكة" : "خلّيه تابع"; var kk = SelKing; OwnKingText = kk == null ? "مفيش ممالك" : kk.Name + (kk.Leader.Length > 0 ? "  (" + kk.Leader + ")" : ""); break; }
                case "mute": FormTitle = "كتم الشات" + who; break;
                case "warn": FormTitle = "تحذير رسمي" + who; MsgBtn = "ابعت التحذير"; break;
                case "pm": FormTitle = "رسالة خاصة" + who; MsgBtn = "ابعت الرسالة"; break;
                case "note": FormTitle = "ملاحظات الإدارة" + who; break;
                case "owned": { FormTitle = "ممتلكاته" + who; var k = SelKing; OwnKingText = k == null ? "مفيش ممالك" : k.Name + (k.Leader.Length > 0 ? "  (" + k.Leader + ")" : ""); break; }
                case "pris": FormTitle = "الأسرى" + who; break;
                case "attr": FormTitle = "نقط الصفات والتركيز" + who; break;
