        public void ExecuteMsgSend()
        {
            var t = Reason();
            if (form == "pm" && t.Length == 0) { ShowResult(false, "اكتب الرسالة الأول"); return; }
            if (form == "warn") Run("تحذير", "warn " + Target + " " + t, false); else Run("رسالة", "pm " + Target + " " + t, false);
