        const float KBarFull = 470f;
        void RefreshK14()
        {
            if (KRows == null) return;
            KRows.Clear();
            var live = LiveKingdoms14();
            var max = Math.Max(1, wkings.Count == 0 ? 1 : wkings.Max(k => k.Towns * 2 + k.Castles));
            foreach (var k in wkings.Skip(kPage * KPage).Take(KPage))
            {
                var wars = WarsOf(live, k.Id);
                var row = new AurVM(k.Id, k.Name, r => { selKing = r.Key; RefreshKings(); })
                    .WithSub("الحاكم: " + (k.Leader.Length > 0 ? k.Leader : "—") + " · " + k.Towns + " مدن · " + k.Castles + " قلاع · " + k.Clans + " عشيرة")
                    .WithTag(wars.Count == 0 ? "سلام" : "حرب مع " + wars.Count).WithNote(wars.Count == 0 ? "" : "حرب مع: " + string.Join("، ", wars.ToArray()))
                    .State(wars.Count == 0, false, wars.Count > 0).Bar(Math.Max(6f, KBarFull * (k.Towns * 2 + k.Castles) / (float)max));
                row.IsSelected = k.Id == selKing; KRows.Add(row);
            }
            var sk = SelKing; SelKingName = sk == null ? "اختار مملكة" : sk.Name;
            if (kOther == selKing) kOther = "";
            var o = wkings.FirstOrDefault(x => x.Id == kOther);
            KOtherText = o == null ? "اختار المملكة التانية" : o.Name;
            if (sk != null && o != null)
            {
                var a = live.FirstOrDefault(x => Sv(Pv(x, "StringId")) == sk.Id); var b = live.FirstOrDefault(x => Sv(Pv(x, "StringId")) == o.Id);
                KWarText = a == null || b == null ? "" : (AtWar14(a, b) ? "دلوقتي: حرب بين " + sk.Name + " و " + o.Name : "دلوقتي: سلام بين " + sk.Name + " و " + o.Name);
            }
            else KWarText = "";
        }
        static List<object> LiveKingdoms14()
        {
            var r = new List<object>();
            try { var ka = Pv(AccessTools.TypeByName("TaleWorlds.CampaignSystem.Kingdom"), "All") as IEnumerable; if (ka != null) foreach (var k in ka) if (!Bv(k, "IsEliminated")) r.Add(k); } catch { }
            return r;
        }
        static MethodInfo atWar14;
        static bool AtWar14(object a, object b)
        {
            try
            {
                if (atWar14 == null) atWar14 = AccessTools.TypeByName("TaleWorlds.CampaignSystem.FactionManager").GetMethod("IsAtWarAgainstFaction", BindingFlags.Static | BindingFlags.Public);
                var v = atWar14.Invoke(null, new[] { a, b }); return v is bool && (bool)v;
            }
            catch { return false; }
        }
        static List<string> WarsOf(List<object> live, string id)
        {
            var r = new List<string>(); var me = live.FirstOrDefault(x => Sv(Pv(x, "StringId")) == id); if (me == null) return r;
            foreach (var k in live) if (k != me && AtWar14(me, k)) r.Add(Sv(Pv(k, "Name")));
            return r;
        }
