                    .WithSub(Mj.S(s, "by", "") + " · " + (mode == "banner" ? "بانر" : mode == "admins" ? "إداريين" : "شات") + (every > 0 ? " · متكرر · الجاي " + Hm(Mj.S(s, "next", "")) : ""))
