                else { var sp = line.IndexOf(' '); text = sp < 0 ? "" : line.Substring(sp + 1); how = a == "chat:banner" ? "بانر" : a == "chat:adminsay" ? "إداريين" : "شات"; }
                AnnList.Add(new AurVM("", text, null).WithTag(how == "إداريين" ? "للإدارة" : "اتبعت").WithTime(Hm(Mj.S(l, "time", ""))).WithSub(Mj.S(l, "byName", "") + " · " + how).State(false, how == "إداريين", false));
