        static string Mask(string id) { return id.Length >= 15 ? id.Substring(0, 7) + "••••" + id.Substring(id.Length - 4) : id; }
        void RefreshBans14(Dictionary<string, object> d)
        {
            BanRows.Clear(); int temp = 0, all = 0;
            foreach (var b in L(d, "bans").OfType<Dictionary<string, object>>().Reverse())
            {
                all++;
                var id = Mj.S(b, "controllerId", ""); var until = Mj.S(b, "until", ""); if (until.Length > 0) temp++;
                string left = "نهائي";
                DateTime u; if (until.Length > 0 && DateTime.TryParseExact(until, "yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture, DateTimeStyles.None, out u))
                { var span = u - DateTime.Now; left = span.TotalMinutes <= 0 ? "خلص" : span.TotalHours < 24 ? "باقي " + Math.Max(1, (int)Math.Ceiling(span.TotalHours)) + " ساعة" : "باقي " + (int)Math.Ceiling(span.TotalDays) + " أيام"; }
                var name = Mj.S(b, "name", "").Length > 0 ? Mj.S(b, "name", "") : "—";
                BanRows.Add(new AurVM(id, name, null).WithSub(Mask(id)).WithNote(Mj.S(b, "reason", "").Length > 0 ? Mj.S(b, "reason", "") : "—").WithTag(Mj.S(b, "by", "")).WithTime(left)
                    .State(false, until.Length > 0, until.Length == 0)
                    .WithA("ارفع الحظر", r => Danger("فك الحظر — " + r.Title, "هيقدر يدخل السيرفر تاني.", false, (x, h) => { AdminClient.Do("unban " + r.Key); Later(1.2, () => AdminClient.Send("!ui bans")); })));
            }
            BansHeader = all + " حظر · " + temp + " مؤقت";
        }
