        static readonly HashSet<string> ResCmds = new HashSet<string> { "gold", "renown", "influence", "skill", "skillreset", "attr", "focus", "troops", "troopsclear", "troopxp", "troopset", "itemset", "prisoners", "prisonersclear", "starter", "undo" };
        static readonly HashSet<string> KickCmds = new HashSet<string> { "kick", "ban", "tban", "banid", "unban", "warn", "mute", "unmute" };
        static readonly HashSet<string> WorldCmds = new HashSet<string> { "give", "take", "kingdom", "vassal", "leave", "kwar", "kpeace", "tp", "relations" };
        void LoadLog14(Dictionary<string, object> d)
        {
            logAll = L(d, "lines").OfType<Dictionary<string, object>>().ToList();
