        }
        void RefreshSel14Stats() { if (Sel != null && Stats != null && Stats.Count > 0) RefreshSel14(); }
        void RefreshLog14()
        {
            LFAll = lf == "all"; LFRes = lf == "res"; LFKick = lf == "kick"; LFWorld = lf == "world"; LFDenied = lf == "denied";
            LogRows.Clear();
            foreach (var h in logAll)
            {
                var act = Mj.S(h, "action", ""); var nm = act.StartsWith("chat:") ? act.Substring(5) : act; var ok = Mj.B(h, "ok", false);
                if (lf == "res" && !ResCmds.Contains(nm)) continue;
                if (lf == "kick" && !KickCmds.Contains(nm) && act != "kick" && act != "ban") continue;
                if (lf == "world" && !WorldCmds.Contains(nm) && !act.StartsWith("leave-fix")) continue;
                if (lf == "denied" && ok && !act.StartsWith("denied") && !act.StartsWith("pin")) continue;
                LogRows.Add(new AurVM("", Mj.S(h, "byName", "").Length > 0 ? Mj.S(h, "byName", "") : "—", null).WithTime(Hm(Mj.S(h, "time", "")))
                    .WithSub(CmdAr(act, Mj.S(h, "reason", ""))).WithNote(Mj.S(h, "targetName", "").Length > 0 ? Mj.S(h, "targetName", "") : "—")
                    .WithTag(ok ? "✓ اتنفّذ" : act.StartsWith("denied") ? "✗ مرفوض" : "✗ فشل").State(ok, false, !ok));
                if (LogRows.Count >= 60) break;
            }
            HasNoLog = LogRows.Count == 0;
        }
