        void RefreshAlerts()
        {
            AlertRows.Clear();
            foreach (var a in alertsAll.Where(x => !ignoredAlerts.Contains(AlertKey(x))))
            {
                var kind = Mj.S(a, "kind", ""); bool high = kind == "pin" || kind == "gold" || kind == "settlements" || kind == "ip";
                var tgt = Mj.S(a, "target", ""); var online = allPlayers.Any(p => Mj.S(p, "controllerId", "") == tgt);
                var row = new AurVM(AlertKey(a), Mj.S(a, "title", ""), null).WithTag(high ? "عالي" : "متوسط").WithTime(Hm(Mj.S(a, "time", "")))
                    .WithSub(Mj.S(a, "text", "")).WithNote(Mj.S(a, "targetName", "")).State(false, !high, high)
                    .WithC("تجاهل", r => { ignoredAlerts.Add(r.Key); RefreshAlerts(); RefreshFeed(); RefreshP14(); });
                var fix = Mj.S(a, "fix", "");
                if (fix.Length > 0 && (CanGold || CanRenown))
                    row.WithB("رجّع القيمة", r => Danger("رجّع القيمة", "القيمة هترجع زي ما كانت قبل التنبيه. تقدر تتراجع بعدها من «تراجع».", false, (x, h) => { AdminClient.Do(fix); ignoredAlerts.Add(r.Key); RefreshAlerts(); }, true));
                if (online) row.WithA("افتح اللاعب", r => { selCid = tgt; SetTab("players"); RefreshList(); RefreshSelected(); RefreshP14(); });
                AlertRows.Add(row);
                if (AlertRows.Count >= 40) break;
            }
            HasNoAlerts = AlertRows.Count == 0;
            var today = alertsAll.Count(x => Recent(Mj.S(x, "time", ""), 24) && !ignoredAlerts.Contains(AlertKey(x)));
            AlertBadge = today > 0 ? (today > 9 ? "9+" : today.ToString(CultureInfo.InvariantCulture)) : "";
        }
