        [DataSourceProperty] public bool AlwaysTimeOff { get { return !alwaysTime; } }
        [DataSourceProperty] public string ServerVer { get { return serverVer; } set { S(ref serverVer, value, "ServerVer"); } }
        public void LoadHealth(Dictionary<string, object> d)
        {
            knownCount = (int)Mj.N(d, "known", 0);
            Health.Clear();
            var up = Mj.N(d, "uptimeMin", 0); var fm = Mj.N(d, "frameMs", 0); var al = (int)Mj.N(d, "alertsToday", 0);
            var date = Mj.S(d, "date", ""); var mode = Mj.S(d, "mode", "");
            var hl = new List<AurVM>();
            hl.Add(new AurVM("", "اللاعبين", null).WithValue(N(d, "online")).WithNote(knownCount + " مسجّل في السيرفر").State(true, false, false));
            hl.Add(new AurVM("", "زمن الفريم", null).WithValue(fm > 0 ? fm.ToString("0.0", CultureInfo.InvariantCulture) + " ms" : "—").WithNote(fm <= 0 ? "بيتقاس" : fm < 40 ? "السيرفر مرتاح" : fm < 100 ? "تقيل شوية" : "تقيل").State(fm > 0 && fm < 40, fm >= 40 && fm < 100, fm >= 100));
            var ls = Mj.S(d, "lastSave", ""); var lsm = Mj.N(d, "lastSaveMin", -1);
            hl.Add(new AurVM("", "آخر حفظ", null).WithValue(ls.Length > 0 ? ls : "—").WithNote(lsm < 0 ? "مش لاقي ملفات الحفظ" : "من " + Dur(lsm)).State(lsm >= 0 && lsm <= 15, lsm > 15, false));
            var stopped = mode.Length > 0 && mode.IndexOf("Play", StringComparison.OrdinalIgnoreCase) < 0;
            hl.Add(new AurVM("", "تاريخ الحملة", null).WithValue(date.Length > 0 ? date : "—").WithNote(stopped ? "الوقت واقف دلوقتي" : "الوقت شغال").State(!stopped, stopped, false));
            var cu = Mj.B(d, "catchUp", false);
            hl.Add(new AurVM("", "مزامنة الدخول", null).WithValue(cu ? "لاعب بيلحق" : "مفيش طابور").WithNote(cu ? "الوقت واقف لحد ما يخلص دخول" : "أي حد يدخل على طول").State(!cu, cu, false));
            hl.Add(new AurVM("", "تنبيهات النهارده", null).WithValue(al.ToString(CultureInfo.InvariantCulture)).WithNote(al == 0 ? "مفيش حاجة غريبة" : "راجعهم في التنبيهات").State(al == 0, al > 0, false));
            AddRtl(Health, hl, 3);
            AlwaysTimeOn = Mj.B(d, "alwaysTime", true);
            TimeInfo = AlwaysTimeOn ? "اللاعبين مايقدروش يوقفوه أو يغيروا سرعته. بيقف لوحده بس وقت دخول لاعب جديد لحد ما يلحق. (اتمنع " + N(d, "timeBlocked") + " طلب إيقاف · اتصلّح " + N(d, "timeFixes") + " مرة)"
                                    : "مقفول من الاستوديو: اللاعبين يقدروا يوقفوا الوقت ويسرّعوه زي Coop العادي.";
            ServerVer = "نظام الإدارة على السيرفر: إصدار " + N(d, "version") + "  ·  شغال من " + Dur(up);
            AdminRows.Clear();
            foreach (var a in L(d, "admins").OfType<Dictionary<string, object>>().OrderByDescending(x => Mj.B(x, "online", false)))
            {
                var lv = Mj.S(a, "level", "");
                AdminRows.Add(new AurVM("", Mj.S(a, "name", ""), null).WithSub((Mj.B(a, "online", false) ? "أونلاين · " : "أوفلاين · ") + N(a, "perms") + " صلاحية")
                    .WithTag(lv == "admin" ? "أدمن" : lv == "moderator" ? "مشرف" : "مراقب").State(Mj.B(a, "online", false), false, false));
            }
            schedAll = L(d, "schedules").OfType<Dictionary<string, object>>().ToList();
            RefreshAnn(); RefreshP14();
        }
        public void ExecuteSaveNow() { Danger("احفظ الحملة دلوقتي", "السيرفر هيعمل حفظ للحملة دلوقتي. ممكن يقف ثانية.", false, (r, h) => AdminClient.Do("save"), true); }
        public void ExecuteRestart10() { ExecuteRestart("10"); }
        public void ExecuteHealthRefresh() { if (!AdminClient.Preview) AdminClient.Send("!ui health"); }

        // ================================================= toast with undo + footer
        bool hasToast, toastOk = true, toastUndo; string toastText = ""; DateTime toastUntil = DateTime.MinValue;
        [DataSourceProperty] public bool HasToast { get { return hasToast; } set { B(ref hasToast, value, "HasToast"); } }
        [DataSourceProperty] public bool ToastOk { get { return toastOk; } set { B(ref toastOk, value, "ToastOk"); OnPropertyChanged("ToastBad"); } }
        [DataSourceProperty] public bool ToastBad { get { return !toastOk; } }
        [DataSourceProperty] public bool ToastUndo { get { return toastUndo; } set { B(ref toastUndo, value, "ToastUndo"); } }
        [DataSourceProperty] public string ToastText { get { return toastText; } set { S(ref toastText, value, "ToastText"); } }
        public void ShowResultU(bool ok, string text, bool canUndo)
        {
            ShowResult(ok, text);
            ToastUndo = canUndo && ok;
            if (ToastUndo) toastUntil = DateTime.UtcNow.AddSeconds(12);
        }
        void Toast14(bool ok, string text)
        {
            ToastText = Cut((text ?? "").Replace("\n", "  ·  "), 170); ToastOk = ok; ToastUndo = false; HasToast = true;
            toastUntil = DateTime.UtcNow.AddSeconds(ok ? 6 : 9);
            LastAction = "آخر أمر: " + Cut((text ?? "").Split('\n')[0], 90) + " · " + DateTime.Now.ToString("HH:mm", CultureInfo.InvariantCulture);
        }
        public void ExecuteUndo() { HasToast = false; AdminClient.Do("undo"); }
        public void ExecuteHideToast() { HasToast = false; }

        // ================================================= confirm with duration + reason
        string confirmTitle = "تأكيد", modalReason = "", durH = "24";
        bool hasDur, hasModalReason, d1h, d1d = true, d3d, d1w;
        [DataSourceProperty] public string ConfirmTitle { get { return confirmTitle; } set { S(ref confirmTitle, value, "ConfirmTitle"); } }
        [DataSourceProperty] public string ModalReason { get { return modalReason; } set { S(ref modalReason, value, "ModalReason"); } }
        [DataSourceProperty] public bool HasDur { get { return hasDur; } set { B(ref hasDur, value, "HasDur"); } }
        [DataSourceProperty] public bool HasModalReason { get { return hasModalReason; } set { B(ref hasModalReason, value, "HasModalReason"); } }
        [DataSourceProperty] public bool D1h { get { return d1h; } set { B(ref d1h, value, "D1h"); } }
        [DataSourceProperty] public bool D1d { get { return d1d; } set { B(ref d1d, value, "D1d"); } }
        [DataSourceProperty] public bool D3d { get { return d3d; } set { B(ref d3d, value, "D3d"); } }
        [DataSourceProperty] public bool D1w { get { return d1w; } set { B(ref d1w, value, "D1w"); } }
        public void ExecuteDur(string h) { durH = h; D1h = h == "1"; D1d = h == "24"; D3d = h == "72"; D1w = h == "168"; }
        // dangerous command: title, what will happen, optional duration chips, a reason box (shown to the player / kept in the log)
        void Danger(string title, string desc, bool timed, Action<string, string> run, bool noReason = false)
        {
            var p = Sel; var who = p == null ? "" : Hero(p);
            var reasonUsed = !noReason;
            Ask((who.Length > 0 && !noReason ? "الأمر ده هيتنفذ على " + who + " وهيتسجل باسمك في السجل. " : "") + desc, () => run((ModalReason ?? "").Trim(), durH));
            ConfirmTitle = title + (who.Length > 0 && !noReason ? " — " + who : "");
            HasDur = timed; HasModalReason = reasonUsed; ModalReason = ""; ExecuteDur("24");
        }

        // ================================================= Ctrl+K palette
        bool hasPalette; string paletteSearch = "";
        [DataSourceProperty] public bool HasPalette { get { return hasPalette; } set { B(ref hasPalette, value, "HasPalette"); } }
        [DataSourceProperty] public string PaletteSearch { get { return paletteSearch; } set { var o = paletteSearch; S(ref paletteSearch, value, "PaletteSearch"); if (o != paletteSearch) RefreshPalette(); } }
        public void ExecutePalette() { HasPalette = !HasPalette; if (HasPalette) { PaletteSearch = ""; RefreshPalette(); } }
        void RefreshPalette()
        {
            PaletteRows.Clear();
            var q = (PaletteSearch ?? "").Trim();
            var tabs = new[] { new[] { "players", "اللاعبين" }, new[] { "world", "الممالك والمدن" }, new[] { "announce", "الإعلانات" }, new[] { "bans", "المحظورين" }, new[] { "log", "السجل" }, new[] { "alerts", "التنبيهات" }, new[] { "server", "السيرفر" } };
            foreach (var t in tabs)
            {
                var tt = t[0];
                if ((tt == "server" && !CanServer) || (tt == "bans" && !CanBan) || (tt == "announce" && !CanAnnounce)) continue;
                if (q.Length > 0 && t[1].IndexOf(q, StringComparison.OrdinalIgnoreCase) < 0) continue;
                PaletteRows.Add(new AurVM(tt, "افتح: " + t[1], r => { HasPalette = false; SetTab(r.Key); if (r.Key == "world") LoadWorld(); }).WithSub("صفحة").WithIcon("List"));
            }
            if (q.Length > 0)
                foreach (var p in allPlayers.Where(x => Hero(x).IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0 || Mj.S(x, "platformName", "").IndexOf(q, StringComparison.OrdinalIgnoreCase) >= 0).Take(4))
                    PaletteRows.Add(new AurVM(Mj.S(p, "controllerId", ""), "اختار: " + Hero(p), r => { HasPalette = false; selCid = r.Key; SetTab("players"); RefreshList(); RefreshSelected(); RefreshP14(); })
                        .WithSub("لاعب · " + (Mj.S(p, "clan", "").Length > 0 ? "عشيرة " + Mj.S(p, "clan", "") : "") + (Mj.S(p, "kingdom", "").Length > 0 ? " · " + Mj.S(p, "kingdom", "") : "")).WithIcon("Users"));
            var who = Sel == null ? "" : Hero(Sel);
            foreach (var a in AllActs().Where(x => x.Allowed))
            {
                if (q.Length > 0 && a.Label.IndexOf(q, StringComparison.OrdinalIgnoreCase) < 0 && a.Desc.IndexOf(q, StringComparison.OrdinalIgnoreCase) < 0) continue;
                var act = a; var catName = CatDefs.First(c => c[0] == act.Cat)[1];
                PaletteRows.Add(new AurVM(a.Key, a.Label + (who.Length > 0 ? " — " + who : ""), r => { HasPalette = false; SetTab("players"); cat = act.Cat; RefreshCats(); if (Sel == null) { ShowResult(false, "اختار لاعب الأول"); return; } act.Run(); })
                    .WithSub(catName + " · " + a.Desc).WithIcon(a.Icon).Flags(a.Danger, a.IsNew));
                if (PaletteRows.Count >= 9) break;
            }
        }

        // ================================================= keys + timers (called every frame by the menu)
        readonly List<KeyValuePair<DateTime, Action>> later14 = new List<KeyValuePair<DateTime, Action>>();
        void Later(double s, Action a) { later14.Add(new KeyValuePair<DateTime, Action>(DateTime.UtcNow.AddSeconds(s), a)); }
        public bool Frame14()   // true = close the menu
        {
            if (HasToast && DateTime.UtcNow >= toastUntil) HasToast = false;
            for (int i = later14.Count - 1; i >= 0; i--) if (later14[i].Key <= DateTime.UtcNow) { var a = later14[i].Value; later14.RemoveAt(i); try { a(); } catch (Exception e) { Log.W("AdminMenu later: " + e.Message); } }
            if (IsPinScreen) return Input.IsKeyReleased(InputKey.Escape);
            var ctrl = Input.IsKeyDown(InputKey.LeftControl) || Input.IsKeyDown(InputKey.RightControl);
            if (ctrl && Input.IsKeyPressed(InputKey.K)) ExecutePalette();
            if (Input.IsKeyReleased(InputKey.Escape))
            {
                if (HasPalette) { HasPalette = false; return false; }
                if (HasConfirm) { ExecuteConfirmNo(); return false; }
                if (form.Length > 0) { ExecuteFormBack(); return false; }
                if (KWarMode) { KWarMode = false; return false; }
                return true;
            }
            return false;
        }
    }

}

