// =====================================================================================
//  system/AdminHost.cs — نظام إدارة اللاعبين (جزء السيرفر)
//  ملف نظام: الاستوديو بيكتبه من جديد مع كل بناء. متعدّلش فيه — أي تعديل هيتمسح.
//
//  بيشتغل على السيرفر بس (على أجهزة اللاعيبة بيفضل نايم ومش بيعمل حاجة).
//  بيتكلم مع الاستوديو عن طريق ملفات في  C:\ProgramData\Aurelion\Admin :
//    state\players.json     اللاعيبة الأونلاين دلوقتي (بيتكتب كل 3 ثواني)
//    state\server.json      حالة نظام الإدارة على السيرفر
//    state\catalog.json     كل أوامر Coop (تبويب CHEATS) بأسمائها ووصفها
//    known-players.json     كل لاعب دخل السيرفر قبل كده
//    bans.json              قايمة الحظر بتاعتنا (بالاسم والسبب) — منها بيتعمل ملف حظر Coop
//    commands\*.json        أوامر من الاستوديو (طرد / حظر / فك حظر / أمر Coop) — بتتنفذ وتتنقل لـ commands\done
//    audit.jsonl            سجل كل فعل: مين عمل إيه لمين وإمتى (مابيتمسحش)
//    alerts.jsonl           تنبيهات الحاجات الغريبة (غش محتمل)
//    admin-config.json      حدود كشف الغش (الاستوديو بيكتبها)
//  كل التعامل مع Coop واللعبة بالـ reflection، فمش بيعتمد على إصدار معين.
// =====================================================================================
using System;
using System.Collections;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using HarmonyLib;

namespace Aurelion.Core
{
    public static class AdminHost
    {
        public const int Version = 9;
        static readonly BindingFlags All = BindingFlags.Instance | BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic;

        public static string Root { get { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData), "Aurelion", "Admin"); } }
        static string StateDir { get { return Path.Combine(Root, "state"); } }
        static string CmdDir { get { return Path.Combine(Root, "commands"); } }

        static bool isServer, gaveUp;
        static DateTime nextProbe = DateTime.MinValue, nextSnap = DateTime.MinValue, nextCmd = DateTime.MinValue, nextKnownSave = DateTime.MinValue, nextWorld = DateTime.MinValue;
        static int probes, errors;
        static DateTime nextTime = DateTime.MinValue;
        static object playerManager, terminator, banList, dispatcher, registry;
        static MethodInfo tryResolve;
        static readonly Dictionary<string, Online> online = new Dictionary<string, Online>();
        static Dictionary<string, object> known;
        static bool knownDirty;
        static DateTime bansStamp = DateTime.MinValue;
        static string banPath, banFormat;
        static readonly Dictionary<string, DateTime> ignoreUntil = new Dictionary<string, DateTime>();   // players an admin just changed (no cheat alert)
        static readonly Dictionary<string, DateTime> alertSeen = new Dictionary<string, DateTime>();
        static AdminCfg cfg = new AdminCfg();
        static DateTime cfgStamp = DateTime.MinValue;

        class Online { public string Ip = ""; public DateTime Since; public Snap Last; }
        class Snap { public DateTime At; public double Gold, Renown, Troops, Skills, Settlements, X, Y; public bool Pos, Prisoner; }
        class AdminCfg
        {
            public bool CheatsEnabled = true;
            public double GoldPerMin = 100000, RenownPerMin = 300, TroopsPerMin = 150, SkillsPerMin = 60, SettlementsPerMin = 2;
            public bool SameIpAlert = true;
            public double MapJump = 80;   // map units between two 3-second checks
            public bool AlwaysTime = true;   // campaign time always runs at normal speed; players can't pause or speed it up
        }

        // ------------------------------------------------------------------ called by SubModule
        static Harmony harmony; static bool clientOff;
        public static void Start(Harmony h) { harmony = h; Log.W("AdminHost v" + Version + " ready (waits until the Coop server is up)"); PerfSetup(); PolicySetup(); try { AdminClient.Start(h); } catch (Exception e) { clientOff = true; Log.W("AdminClient off: " + (e.InnerException ?? e).Message); } }


        // ===== policy: "Send troops" is switched off for everybody (siege / battle / hideout auto-orders) =====
        // The option lives in the game's encounter menus, so this patch has to run on the players' machines (Aurelion.Core ships with Coop).
        static void PolicySetup()
        {
            try
            {
                int n = 0;
                n += HideOption("TaleWorlds.CampaignSystem.CampaignBehaviors.EncounterGameMenuBehavior", "game_menu_encounter_order_attack_on_condition", "game_menu_encounter_order_attack_on_consequence");
                n += HideOption("TaleWorlds.CampaignSystem.CampaignBehaviors.HideoutCampaignBehavior", "game_menu_send_troops_hideout_on_condition", "game_menu_encounter_send_troops_on_consequence");
                Log.W("Policy: Send troops OFF (" + n + " menu methods patched)");
            }
            catch (Exception e) { Log.W("PolicySetup: " + (e.InnerException ?? e).Message); }
        }

        static int HideOption(string type, string cond, string cons)
        {
            int n = 0;
            var t = AccessTools.TypeByName(type);
            if (t == null) { Log.W("Policy: type not found " + type); return 0; }
            var last = new HarmonyMethod(typeof(AdminHost).GetMethod("PolicyHide", BindingFlags.Static | BindingFlags.Public)) { priority = Priority.Last };
            var c = AccessTools.Method(t, cond);
            if (c != null) { harmony.Patch(c, null, last); n++; } else Log.W("Policy: method not found " + type + "::" + cond);
            var q = AccessTools.Method(t, cons);
            if (q != null) { harmony.Patch(q, new HarmonyMethod(typeof(AdminHost).GetMethod("PolicySkip", BindingFlags.Static | BindingFlags.Public)) { priority = Priority.First }); n++; } else Log.W("Policy: method not found " + type + "::" + cons);
            return n;
        }

        public static void PolicyHide(ref bool __result) { __result = false; }
        public static bool PolicySkip() { return false; }

        public static void Tick()
        {
            PerfFrame();
            if (!isServer && !clientOff) { try { AdminClient.Tick(); } catch (Exception e) { clientOff = true; Log.W("AdminClient off: " + (e.InnerException ?? e).Message); } }   // the in-game admin menu (players' machines)
            if (gaveUp) return;
            var now = DateTime.UtcNow;
            try
            {
                if (!isServer)
                {
                    if (now < nextProbe) return;
                    nextProbe = now.AddSeconds(5);
                    if (++probes > 720) { gaveUp = true; return; }   // ~1 hour: this is a player's game, not the server
                    if (!Probe()) return;
                }
                if (now >= nextCmd) { nextCmd = now.AddSeconds(1); ProcessCommands(); SyncBans(false); LoadCfg(); LoadAdmins(); GatewayStart(); LoadTestMode(); SaveLaunchers(false); }
                if (now >= nextSnap) { nextSnap = now.AddSeconds(3); Snapshot(); }
                if (now >= nextWorld) { nextWorld = now.AddSeconds(60); WriteWorld(); SyncBans(true); }
                RunMainQueue(); RunLater();
                if (now >= nextSched) { nextSched = now.AddSeconds(5); ProcessSchedules(); }
                if (now >= nextTime) { nextTime = now.AddSeconds(4); TimeKeep(); }
                if (knownDirty && now >= nextKnownSave) { nextKnownSave = now.AddSeconds(30); SaveKnown(); }
                errors = 0;
            }
            catch (Exception e)
            {
                if (++errors <= 20) Log.W("AdminHost.Tick: " + e);
                if (errors > 200) { gaveUp = true; Log.W("AdminHost stopped after repeated errors"); }
            }
        }

        // ------------------------------------------------------------------ finding Coop's services
        internal static object Resolve(string typeName)
        {
            try
            {
                if (tryResolve == null)
                {
                    var cp = AccessTools.TypeByName("GameInterface.ContainerProvider");
                    if (cp == null) return null;
                    tryResolve = cp.GetMethods(BindingFlags.Static | BindingFlags.Public | BindingFlags.NonPublic)
                        .FirstOrDefault(m => m.Name == "TryResolve" && m.IsGenericMethodDefinition && m.GetParameters().Length == 1);
                    if (tryResolve == null) return null;
                }
                var t = AccessTools.TypeByName(typeName);
                if (t == null) return null;
                var args = new object[1];
                var ok = tryResolve.MakeGenericMethod(t).Invoke(null, args);
                return ok is bool && (bool)ok ? args[0] : null;
            }
            catch (Exception e) { Log.W("Resolve " + typeName + ": " + (e.InnerException ?? e).Message); return null; }
        }

        static bool Probe()
        {
            if (Resolve("Coop.Core.Server.ICoopServer") == null) return false;
            playerManager = Resolve("GameInterface.Services.Players.IPlayerManager");
            if (playerManager == null) return false;
            terminator = Resolve("Coop.Core.Server.Connections.IJoinPeerTerminator");
            banList = Resolve("Coop.Core.Server.Connections.ISteamBanList");
            registry = Resolve("Common.Commands.ICoopCommandRegistry");
            var argsFactory = Resolve("Common.Commands.ICoopCommandArgsFactory");
            try
            {
                var dt = AccessTools.TypeByName("GameInterface.Services.LiveTesting.LiveTestCommandDispatcher");
                if (dt != null)
                {
                    var inst = BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic;
                    var c2 = dt.GetConstructors(inst).FirstOrDefault(c => c.GetParameters().Length == 2);
                    if (c2 != null && registry != null && argsFactory != null) dispatcher = c2.Invoke(new[] { registry, argsFactory });
                    else { var c0 = dt.GetConstructors(inst).FirstOrDefault(c => c.GetParameters().Length == 0); if (c0 != null) dispatcher = c0.Invoke(null); }
                }
            }
            catch (Exception e) { Log.W("dispatcher: " + (e.InnerException ?? e).Message); }
            isServer = true; serverSince = DateTime.UtcNow;
            Directory.CreateDirectory(StateDir); Directory.CreateDirectory(CmdDir); Directory.CreateDirectory(Path.Combine(CmdDir, "done"));
            try
            {
                var sb = AccessTools.TypeByName("Coop.Core.Server.Connections.SteamBanList");
                var rp = sb == null ? null : sb.GetMethods(All).FirstOrDefault(m => m.Name == "ResolvePath" && m.IsStatic && m.GetParameters().Length == 0);
                if (rp != null) banPath = rp.Invoke(null, null) as string;
            }
            catch (Exception e) { Log.W("ban path: " + (e.InnerException ?? e).Message); }
            if (string.IsNullOrEmpty(banPath)) banPath = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "Mount and Blade II Bannerlord", "CoopData", "DedicatedServer", "steam-bans.json");
            try { var f = Path.Combine(StateDir, "ban-format.txt"); if (File.Exists(f)) banFormat = File.ReadAllText(f).Trim(); } catch { }
            LoadKnown(); LoadCfg();
            WriteCatalog();
            SyncBans(true);
            WriteServerState();
            PatchChat();
            Audit("system", "النظام", "server-start", "", "", "", true, "نظام الإدارة اشتغل على السيرفر");
            Log.W("AdminHost: server mode ON (players=" + (playerManager != null) + " kick=" + (terminator != null) + " bans=" + (banList != null) + " commands=" + (dispatcher != null) + ") banFile=" + banPath);
            return true;
        }

        static void WriteServerState()
        {
            var d = new Dictionary<string, object>();
            d["version"] = Version; d["started"] = Iso(DateTime.Now); d["kick"] = terminator != null; d["ban"] = banList != null;
            d["commands"] = dispatcher != null; d["banFile"] = banPath ?? ""; d["banFormat"] = banFormat ?? ""; d["build"] = Rules.BuildVersion;
            WriteJson(Path.Combine(StateDir, "server.json"), d);
        }

        // ------------------------------------------------------------------ players
        static IEnumerable<object> Players()
        {
            var p = Get(playerManager, "Players") as IEnumerable;
            if (p == null) yield break;
            foreach (var x in p) if (x != null) yield return x;
        }

        static object Peer(string controllerId)
        {
            try
            {
                var m = playerManager.GetType().GetMethods(All).FirstOrDefault(x => x.Name == "TryGetPeer" && x.GetParameters().Length == 2 && x.GetParameters()[0].ParameterType == typeof(string));
                if (m == null) return null;
                var a = new object[] { controllerId, null };
                var ok = m.Invoke(playerManager, a);
                return ok is bool && (bool)ok ? a[1] : null;
            }
            catch { return null; }
        }

        static void PeerInfo(object peer, out string ip, out int port, out int ping)
        {
            ip = ""; port = 0; ping = -1;
            if (peer == null) return;
            try
            {
                var ep = Get(peer, "EndPoint") ?? Get(peer, "RemoteEndPoint");
                var ipe = (ep ?? peer) as System.Net.IPEndPoint;
                if (ipe != null) { ip = ipe.Address.ToString(); port = ipe.Port; }
                else { var s = Convert.ToString(ep ?? peer); var i = s.LastIndexOf(':'); ip = i > 0 ? s.Substring(0, i) : s; }
                if (ip.StartsWith("::ffff:")) ip = ip.Substring(7);
                var pg = Get(peer, "Ping") ?? Get(peer, "RoundTripTime");
                if (pg != null) ping = Convert.ToInt32(pg, CultureInfo.InvariantCulture);
            }
            catch { }
        }

        static MethodInfo heroFind; static bool heroLogged;
        static object FindHero(string heroId, object player)
        {
            object h = null;
            var heroType = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Hero");
            if (heroType == null) return null;
            if (!string.IsNullOrEmpty(heroId))
            {
                // 1) Hero.Find(stringId) - campaign object manager (heroes made at runtime live here)
                try
                {
                    if (heroFind == null) heroFind = heroType.GetMethods(BindingFlags.Static | BindingFlags.Public).FirstOrDefault(m => m.Name == "Find" && m.GetParameters().Length == 1 && m.GetParameters()[0].ParameterType == typeof(string));
                    if (heroFind != null) h = heroFind.Invoke(null, new object[] { heroId });
                }
                catch { }
                // 2) Coop object manager
                if (h == null) h = CoopObject(heroType, heroId);
                // 3) scan all heroes
                if (h == null) h = Scan(Get(heroType, "AllAliveHeroes") as IEnumerable, heroId) ?? Scan(Get(heroType, "DeadOrDisabledHeroes") as IEnumerable, heroId);
                // 4) MBObjectManager
                if (h == null)
                    try
                    {
                        var mgrType = AccessTools.TypeByName("TaleWorlds.ObjectSystem.MBObjectManager");
                        var mgr = Get(mgrType, "Instance");
                        var gm = mgrType.GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(m => m.Name == "GetObject" && m.IsGenericMethodDefinition && m.GetParameters().Length == 1 && m.GetParameters()[0].ParameterType == typeof(string));
                        h = gm.MakeGenericMethod(heroType).Invoke(mgr, new object[] { heroId });
                    }
                    catch { }
            }
            // 5) through the player's party
            if (h == null && player != null)
            {
                var pid = Convert.ToString(Get(player, "MobilePartyId"));
                if (!string.IsNullOrEmpty(pid))
                {
                    var mpType = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Party.MobileParty");
                    var party = CoopObject(mpType, pid) ?? Scan(Get(mpType, "All") as IEnumerable, pid);
                    if (party != null) h = Get(party, "LeaderHero");
                }
            }
            if (h == null && !heroLogged) { heroLogged = true; Log.W("AdminHost: hero not found for id=" + heroId + " party=" + Convert.ToString(Get(player, "MobilePartyId"))); }
            return h;
        }

        static object Scan(IEnumerable all, string id)
        {
            if (all == null) return null;
            try { foreach (var o in all) if (o != null && Convert.ToString(Get(o, "StringId")) == id) return o; } catch { }
            return null;
        }

        static object coopObjMgr; static MethodInfo coopTryGet;
        static object CoopObject(Type t, string id)
        {
            if (t == null || string.IsNullOrEmpty(id)) return null;
            try
            {
                if (coopObjMgr == null)
                {
                    var it = AccessTools.TypeByName("GameInterface.Services.ObjectManager.IObjectManager");
                    if (it == null) return null;
                    coopObjMgr = Resolve(it.FullName);
                    if (coopObjMgr == null) return null;
                    coopTryGet = it.GetMethods().FirstOrDefault(m => m.Name == "TryGetObject" && m.IsGenericMethodDefinition && m.GetParameters().Length == 2 && m.GetParameters()[0].ParameterType == typeof(string));
                }
                if (coopTryGet == null) return null;
                var args = new object[] { id, null };
                var ok = coopTryGet.MakeGenericMethod(t).Invoke(coopObjMgr, args);
                return ok is bool && (bool)ok ? args[1] : null;
            }
            catch { return null; }
        }

        static MethodInfo getSkill; static IEnumerable skillsAll;
        static bool skillsLogged;
        static IEnumerable AllSkills()
        {
            foreach (var n in new[] { "TaleWorlds.CampaignSystem.Extensions.Skills", "TaleWorlds.Core.Skills" })
            {
                var t = AccessTools.TypeByName(n);
                var a = t == null ? null : Get(t, "All") as IEnumerable;
                if (a != null && a.Cast<object>().Any()) return a;
            }
            try
            {   // MBObjectManager.Instance.GetObjectTypeList<SkillObject>()
                var so = AccessTools.TypeByName("TaleWorlds.Core.SkillObject");
                var mgrType = AccessTools.TypeByName("TaleWorlds.ObjectSystem.MBObjectManager");
                var mgr = Get(mgrType, "Instance");
                var m = mgrType.GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(x => x.Name == "GetObjectTypeList" && x.IsGenericMethodDefinition && x.GetParameters().Length == 0);
                var a = m == null ? null : m.MakeGenericMethod(so).Invoke(mgr, null) as IEnumerable;
                if (a != null && a.Cast<object>().Any()) return a;
            }
            catch { }
            if (!skillsLogged) { skillsLogged = true; Log.W("AdminHost: skills list not found"); }
            return null;
        }

        static Dictionary<string, object> Skills(object hero, out double total)
        {
            total = 0; var d = new Dictionary<string, object>();
            try
            {
                if (skillsAll == null) skillsAll = AllSkills();
                if (getSkill == null) getSkill = hero.GetType().GetMethods(BindingFlags.Instance | BindingFlags.Public).FirstOrDefault(m => m.Name == "GetSkillValue" && m.GetParameters().Length == 1);
                if (skillsAll == null || getSkill == null) return d;
                foreach (var s in skillsAll)
                {
                    var v = Convert.ToDouble(getSkill.Invoke(hero, new[] { s }), CultureInfo.InvariantCulture);
                    d[Convert.ToString(Get(s, "StringId"))] = v; total += v;
                }
            }
            catch { }
            return d;
        }

        static void Snapshot()
        {
            var list = new List<object>();
            var seen = new HashSet<string>();
            var now = DateTime.Now;
            var byIp = new Dictionary<string, List<string>>();
            foreach (var p in Players())
            {
                var cid = Convert.ToString(Get(p, "ControllerId"));
                if (string.IsNullOrEmpty(cid)) continue;
                var peer = Peer(cid);
                if (peer == null) continue;   // registered but not connected
                seen.Add(cid);
                string ip; int port, ping; PeerInfo(peer, out ip, out port, out ping);
                var heroId = Convert.ToString(Get(p, "HeroId"));
                var hero = FindHero(heroId, p);
                var e = new Dictionary<string, object>();
                e["controllerId"] = cid; e["steam64"] = IsSteam64(cid); e["platformName"] = Str(Get(p, "PlatformName"));
                e["heroId"] = heroId; e["ip"] = ip; e["port"] = port; e["ping"] = ping;
                e["clanId"] = Str(Get(p, "ClanId")); e["partyId"] = Str(Get(p, "MobilePartyId"));
                double gold = 0, renown = 0, troops = 0, skillTotal = 0, setCount = 0;
                if (hero != null)
                {
                    e["heroName"] = Str(Get(hero, "Name"));
                    gold = Num(Get(hero, "Gold")); e["gold"] = gold;
                    e["level"] = Num(Get(hero, "Level"));
                    e["hp"] = Num(Get(hero, "HitPoints"));
                    e["isPrisoner"] = Get(hero, "IsPrisoner") is bool && (bool)Get(hero, "IsPrisoner");
                    var clan = Get(hero, "Clan");
                    if (clan != null)
                    {
                        e["clan"] = Str(Get(clan, "Name")); renown = Num(Get(clan, "Renown")); e["renown"] = renown;
                        e["tier"] = Num(Get(clan, "Tier")); e["influence"] = Num(Get(clan, "Influence"));
                        var k = Get(clan, "Kingdom"); e["kingdom"] = k == null ? "" : Str(Get(k, "Name")); e["kingdomId"] = k == null ? "" : Str(Get(k, "StringId"));
                        if (Str(e["clanId"]).Length == 0) e["clanId"] = Str(Get(clan, "StringId"));
                        var names = new List<object>(); var sids = new List<object>();
                        var sets = Get(clan, "Settlements") as IEnumerable;
                        if (sets != null) foreach (var s in sets) { names.Add(Str(Get(s, "Name"))); sids.Add(Str(Get(s, "StringId"))); }
                        setCount = names.Count; e["settlements"] = names; e["settlementIds"] = sids;
                    }
                    var party = Get(hero, "PartyBelongedTo");
                    if (party != null)
                    {
                        if (Str(e["partyId"]).Length == 0) e["partyId"] = Str(Get(party, "StringId"));
                        troops = Num(Get(Get(party, "MemberRoster"), "TotalManCount")); e["troops"] = troops;
                        e["prisoners"] = Num(Get(Get(party, "PrisonRoster"), "TotalManCount"));
                    }
                    e["skills"] = Skills(hero, out skillTotal); e["skillTotal"] = skillTotal;
                }
                Online o;
                if (!online.TryGetValue(cid, out o))
                {
                    o = new Online { Ip = ip, Since = now }; online[cid] = o;
                    Audit("system", "النظام", "join", cid, Str(e.ContainsKey("heroName") ? e["heroName"] : e["platformName"]), "", true, "دخل السيرفر من " + ip);
                    TestGate(cid, ip, Str(e.ContainsKey("heroName") ? e["heroName"] : e["platformName"]));
                }
                o.Ip = ip;
                e["since"] = Iso(o.Since);
                var cur = new Snap { At = DateTime.UtcNow, Gold = gold, Renown = renown, Troops = troops, Skills = skillTotal, Settlements = setCount };
                if (hero != null)
                {
                    try { var pp = Get(hero, "PartyBelongedTo"); double px, py; if (pp != null && PartyPos(pp, out px, out py)) { cur.X = px; cur.Y = py; cur.Pos = true; } } catch { }
                    cur.Prisoner = e.ContainsKey("isPrisoner") && e["isPrisoner"] is bool && (bool)e["isPrisoner"];
                    CheckCheat(cid, e, o.Last, cur); o.Last = cur;
                }
                Remember(cid, e);
                if (ip.Length > 0) { List<string> l; if (!byIp.TryGetValue(ip, out l)) byIp[ip] = l = new List<string>(); l.Add(cid); }
                list.Add(e);
            }
            foreach (var gone in online.Keys.Where(k => !seen.Contains(k)).ToList())
            {
                Audit("system", "النظام", "leave", gone, KnownName(gone), "", true, "خرج من السيرفر");
                authed.Remove(gone);
                online.Remove(gone); MarkSeen(gone);
            }
            if (cfg.CheatsEnabled && cfg.SameIpAlert)
                foreach (var kv in byIp.Where(x => x.Value.Count > 1))
                    Alert("same-ip", string.Join(",", kv.Value), "أكتر من حساب من نفس الـIP", kv.Value.Count + " حسابات أونلاين من " + kv.Key + ": " + string.Join(" ، ", kv.Value.Select(KnownName)));
            var d = new Dictionary<string, object>();
            lastList = list; gwPlayers = list.Count;
            FlushPendingUi();
            d["updated"] = Iso(now); d["serverRunning"] = true; d["players"] = list;
            WriteJson(Path.Combine(StateDir, "players.json"), d);
        }

        static void CheckCheat(string cid, Dictionary<string, object> e, Snap a, Snap b)
        {
            if (!cfg.CheatsEnabled || a == null) return;
            DateTime until;
            if (ignoreUntil.TryGetValue(cid, out until) && DateTime.UtcNow < until) return;
            var mins = Math.Max(1.0 / 60, (b.At - a.At).TotalMinutes);
            var name = Str(e.ContainsKey("heroName") ? e["heroName"] : cid);
            Action<string, string, double, double, string> chk = (kind, label, before, after, unit) =>
            {
                double limit = kind == "gold" ? cfg.GoldPerMin : kind == "renown" ? cfg.RenownPerMin : kind == "troops" ? cfg.TroopsPerMin : kind == "skills" ? cfg.SkillsPerMin : cfg.SettlementsPerMin;
                var diff = after - before;
                if (limit > 0 && diff > 0 && diff / mins > limit)
                    Alert(kind, cid, label + " زاد بسرعة غريبة", name + ": " + label + " زاد " + diff.ToString("N0", CultureInfo.InvariantCulture) + " " + unit + " في " + Math.Max(1, (int)Math.Round(mins * 60)) + " ثانية (من " + before.ToString("N0", CultureInfo.InvariantCulture) + " لـ " + after.ToString("N0", CultureInfo.InvariantCulture) + ")", kind == "gold" ? "gold " + cid + " " + Inv(before) : kind == "renown" ? "renown " + cid + " -" + Inv(diff) : "");
            };
            chk("gold", "الفلوس", a.Gold, b.Gold, "دينار");
            chk("renown", "الشهرة", a.Renown, b.Renown, "");
            chk("troops", "عدد الجنود", a.Troops, b.Troops, "جندي");
            chk("skills", "مجموع المهارات", a.Skills, b.Skills, "نقطة");
            chk("settlements", "عدد الممتلكات", a.Settlements, b.Settlements, "");
            if (a.Pos && b.Pos && !a.Prisoner && !b.Prisoner && cfg.MapJump > 0)
            {
                var dist = Math.Sqrt((a.X - b.X) * (a.X - b.X) + (a.Y - b.Y) * (a.Y - b.Y));
                if (dist > cfg.MapJump * Math.Max(1.0, (b.At - a.At).TotalSeconds / 3.0))
                    Alert("speed", cid, "جيش اتنقل بسرعة غريبة", name + ": جيشه اتحرك " + dist.ToString("N0", CultureInfo.InvariantCulture) + " وحدة على الخريطة في " + Math.Max(1, (int)Math.Round((b.At - a.At).TotalSeconds)) + " ثانية — ممكن نقل بالغش أو سرعة غريبة.");
            }
        }

        static void Alert(string kind, string cid, string title, string text, string fix = "")
        {
            var key = kind + "|" + cid; DateTime last;
            if (alertSeen.TryGetValue(key, out last) && (DateTime.UtcNow - last).TotalMinutes < 10) return;
            alertSeen[key] = DateTime.UtcNow;
            var d = new Dictionary<string, object>();
            d["time"] = Iso(DateTime.Now); d["kind"] = kind; d["target"] = cid; d["targetName"] = cid.Contains(",") ? "" : KnownName(cid); d["title"] = title; d["text"] = text; if (fix.Length > 0) d["fix"] = fix;
            AppendLine(Path.Combine(Root, "alerts.jsonl"), d);
        }

