        static readonly HashSet<string> Disabled = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { };   // kingdom/vassal/leave back on: the 06-11 crash was save003 vs the patched More Nations map, not these commands
        static readonly HashSet<string> NoPlayerCmds = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "help", "menu", "players", "say", "unban", "cmd", "restart", "kwar", "kpeace", "undo", "banner", "adminsay", "sched", "unsched", "banid", "save" };

        // reply: chat line, or a hidden "result" packet when the request came from the in-game menu
        static void Reply(object peer, string cid, bool ui, bool ok, string text)
        {
            if (!ui) { Say(peer, cid, text); return; }
            var d = new Dictionary<string, object>(); d["ok"] = ok; d["text"] = text;
            UiSend(peer, cid, "result", d);
        }

        static string Fmt(double v) { return v.ToString("N0", CultureInfo.InvariantCulture); }
        static string Inv(double v) { return Math.Round(v).ToString("0", CultureInfo.InvariantCulture); }

        static void ChatCommand(object peer, string cid, string line, bool ui = false)
        {
            var tk = Tokens(line);
            if (tk.Count == 0) return;
            var name = tk[0].ToLowerInvariant(); tk.RemoveAt(0);
            var perms = PermsOf(cid); var by = AdminName(cid);
            ChatCmd cmd;
            if (!ChatCmds.TryGetValue(name, out cmd)) { Reply(peer, cid, ui, false, "أمر مش معروف: !" + name + " — اكتب !help"); return; }
            if (cmd.Perm.Length > 0 && !perms.Contains(cmd.Perm)) { Reply(peer, cid, ui, false, "مش مسموحلك بالأمر ده (!" + name + ")."); Audit(cid, by, "denied:" + name, "", "", line, false, "مرفوض — مفيش صلاحية"); return; }
            if (tk.Count < cmd.Args) { Reply(peer, cid, ui, false, "الاستخدام: " + cmd.Usage); return; }
            if (Disabled.Contains(name)) { Reply(peer, cid, ui, false, "الأمر ده موقوف مؤقتاً: أوامر الممالك بتاعة Coop تجريبية وبتوقّع السيرفر. هترجع لما نلاقي طريقة آمنة."); return; }
            string err; Dictionary<string, object> p = null; string target = "", tname = "";
            bool needsPlayer = !NoPlayerCmds.Contains(name);
            if (needsPlayer)
            {
                p = FindPlayer(tk[0], out err);
                if (p == null) { Reply(peer, cid, ui, false, err); return; }
                target = Mj.S(p, "controllerId", ""); tname = PName(p);
            }
            var heroId = p == null ? "" : Mj.S(p, "heroId", ""); var heroName = p == null ? "" : Mj.S(p, "heroName", heroId);
            var rest = string.Join(" ", tk.Skip(needsPlayer ? 1 : 0));
            var arg1 = tk.Count > 1 ? tk[1] : "";
            var after1 = string.Join(" ", tk.Skip(needsPlayer ? 2 : 1));
            bool ok = true; string output; string undoLine = null, undoLabel = null;
            switch (name)
            {
                case "help":
                    Reply(peer, cid, ui, true, "أوامر الإدارة (" + by + "):\n" + string.Join("\n", ChatCmds.Values.Where(c => c.Perm.Length == 0 || perms.Contains(c.Perm)).Select(c => c.Usage + "  —  " + c.Help)) + "\nاللاعب = رقمه من !players أو أول اسمه أو Steam64.");
                    return;
                case "menu":
                    UiHello(peer, cid, false); return;
                case "players":
                    {
                        var l = OnlineSorted();
                        Reply(peer, cid, ui, true, l.Count == 0 ? "مفيش حد أونلاين." : "أونلاين (" + l.Count + "):\n" + string.Join("\n", l.Select((x, i) => "#" + (i + 1) + "  " + PName(x) + "  •  " + Mj.S(x, "clan", "") + "  •  " + Fmt(Mj.N(x, "gold", 0)) + " دينار")));
                        return;
                    }
                case "info":
                    Reply(peer, cid, ui, true, PName(p) + "\nالعشيرة: " + Mj.S(p, "clan", "—") + "  •  المملكة: " + Mj.S(p, "kingdom", "—") + "\nالفلوس: " + Fmt(Mj.N(p, "gold", 0)) + "  •  الشهرة: " + Fmt(Mj.N(p, "renown", 0)) + "  •  الجنود: " + Fmt(Mj.N(p, "troops", 0)) + "\nSteam64: " + target + (perms.Contains("ban") ? "  •  IP: " + Mj.S(p, "ip", "") : "") + "  •  تحذيرات: " + Warnings(target).Count);
                    return;
                case "kick":
                    output = Kick(target, rest.Length > 0 ? rest : "اتطردت بواسطة الإدارة", out ok); break;
                case "ban":
                    output = ServerBan(target, tname, rest, by, 0); break;
                case "tban":
                    {
                        double h; if (!double.TryParse(arg1, NumberStyles.Float, CultureInfo.InvariantCulture, out h) || h <= 0) { Reply(peer, cid, ui, false, "عدد الساعات مش صحيح"); return; }
                        output = ServerBan(target, tname, after1, by, h); break;
                    }
                case "unban":
                    output = ServerUnban(tk[0]); target = tk[0]; tname = KnownName(tk[0]); ok = output.StartsWith("✓"); break;
                case "warn":
                    {
                        var n = AddWarning(target, by, rest);
                        Say(Peer(target), target, "[تحذير من الإدارة]  " + (rest.Length > 0 ? rest : "التزم بقواعد السيرفر") + "  (التحذير رقم " + n + ")");
                        output = "✓ اتحذّر — ده التحذير رقم " + n; break;
                    }
                case "mute":
                    {
                        double m; if (!double.TryParse(arg1, NumberStyles.Float, CultureInfo.InvariantCulture, out m) || m < 0) { Reply(peer, cid, ui, false, "عدد الدقايق مش صحيح"); return; }
                        SetMute(target, m);
                        Say(Peer(target), target, "[الإدارة]  اتكتمت في الشات " + (m <= 0 ? "لحد ما الإدارة تفك الكتم" : Inv(m) + " دقيقة"));
                        output = "✓ اتكتم " + (m <= 0 ? "(دايم)" : Inv(m) + " دقيقة"); undoLine = "unmute " + target; undoLabel = "فك الكتم عن " + tname; break;
                    }
                case "unmute":
                    SetMute(target, -1); Say(Peer(target), target, "[الإدارة]  اتفك الكتم عنك"); output = "✓ اتفك الكتم"; break;
                case "pm":
                    Say(Peer(target), target, "[رسالة من الإدارة — " + by + "]  " + rest); output = "✓ الرسالة وصلت"; break;
                case "say":
                    Broadcast("[إعلان من " + by + "]  " + rest); output = "✓ اتبعت لكل اللاعيبة"; break;
                case "unstuck":
                    output = Run("coop.unstuck", new List<string> { target }, out ok); break;
                case "free":
                    output = Run("coop.debug.player_captivity.release_player", new List<string> { heroId }, out ok); break;
                case "tp":
                    {
                        var st = FindIn("world.json", "settlements", rest);
                        if (st == null) { Reply(peer, cid, ui, false, "مش لاقي مدينة اسمها \"" + rest + "\""); return; }
                        output = Run("coop.debug.mobile_party.move_to_settlement", new List<string> { Mj.S(p, "partyId", ""), Mj.S(st, "id", ""), "true" }, out ok) + " ← " + Mj.S(st, "name", "");
                        break;
                    }
                case "goto":
                case "bring":
                    {
                        var me = lastList.OfType<Dictionary<string, object>>().FirstOrDefault(x => Mj.S(x, "controllerId", "") == cid);
                        if (me == null) { Reply(peer, cid, ui, false, "لازم تكون جوه الحملة بجيشك"); return; }
                        var mover = name == "goto" ? me : p; var anchor = name == "goto" ? p : me;
                        output = MoveNextTo(Mj.S(mover, "partyId", ""), Mj.S(anchor, "partyId", ""), out ok); break;
                    }
                case "gold":
                    {
                        double v; var a = arg1.Replace(",", "");
                        if (!double.TryParse(a, NumberStyles.Float, CultureInfo.InvariantCulture, out v)) { Reply(peer, cid, ui, false, "المبلغ مش رقم"); return; }
                        var h = FindHero(heroId, null); var cur = Num(Get(h, "Gold"));
                        var nv = Math.Max(0, Math.Round(a.StartsWith("+") || a.StartsWith("-") ? cur + v : v));
                        output = Run("coop.debug.hero.set_gold_state", new List<string> { heroId, Inv(nv) }, out ok) + "  (" + Fmt(cur) + " ← " + Fmt(nv) + ")";
                        undoLine = "gold " + target + " " + Inv(cur); undoLabel = "فلوس " + tname + " ترجع " + Fmt(cur);
                        break;
                    }
                case "renown":
                case "influence":
                    {
                        double v; if (!double.TryParse(arg1.TrimStart('+'), NumberStyles.Float, CultureInfo.InvariantCulture, out v)) { Reply(peer, cid, ui, false, "اكتب رقم زي +100 أو -50"); return; }
                        output = Run(name == "renown" ? "coop.debug.clan.add_renown" : "coop.debug.clan.add_influence", new List<string> { Mj.S(p, "clanId", ""), Inv(v) }, out ok);
                        undoLine = name + " " + target + " " + (v >= 0 ? "-" : "+") + Inv(Math.Abs(v)); undoLabel = (name == "renown" ? "شهرة " : "نفوذ ") + tname + " " + (v >= 0 ? "-" : "+") + Inv(Math.Abs(v));
                        break;
                    }
                case "skill":
                    {
                        var skills = Mj.D(p, "skills"); var sk = skills.Keys.FirstOrDefault(k => k.StartsWith(arg1, StringComparison.OrdinalIgnoreCase)) ?? arg1;
                        output = Run("coop.debug.hero_developer.set_skill", new List<string> { heroId, sk, tk[2], Inv(Mj.N(skills, sk, 0)) }, out ok);
                        undoLine = "skill " + target + " " + sk + " " + Inv(Mj.N(skills, sk, 0)); undoLabel = sk + " لـ " + tname + " ترجع " + Inv(Mj.N(skills, sk, 0));
                        break;
                    }
                case "skillreset":
                    output = Run("coop.debug.hero_developer.reset_skills", new List<string> { heroId }, out ok); break;
                case "attr":
                    output = Run("coop.debug.hero_developer.add_attribute_points", new List<string> { heroId, arg1 }, out ok); break;
                case "focus":
                    output = Run("coop.debug.hero_developer.add_focus_points", new List<string> { heroId, arg1 }, out ok); break;
                case "troops":
                    output = Run("coop.debug.mobile_party.add_troops", new List<string> { heroName }, out ok); break;
                case "troopsclear":
                    output = ClearTroops(heroId, Mj.S(p, "partyId", ""), out ok); break;
                case "troopxp":
                    output = Run("coop.debug.mobile_party.add_troop_xp", new List<string> { heroName, arg1 }, out ok); break;
                case "troopset":
                case "itemset":
                    {
                        int d; if (!int.TryParse(tk[2].Replace("+", ""), NumberStyles.Integer, CultureInfo.InvariantCulture, out d) || d == 0) { Reply(peer, cid, ui, false, "اكتب عدد زي +10 أو -5"); return; }
                        var pp = p; var what = arg1; var isTroop = name == "troopset"; var lineCopy = line;
                        OnMain(() =>
                        {
                            bool ok2; var o2 = isTroop ? TroopSet(pp, what, d, out ok2) : ItemSet(pp, what, d, out ok2);
                            if (ok2) SetUndo(cid, name + " " + target + " " + what + " " + (d > 0 ? "-" : "+") + Math.Abs(d), (d > 0 ? "شيل " : "رجّع ") + Math.Abs(d) + " " + what + " من " + tname);
                            ignoreUntil[target] = DateTime.UtcNow.AddSeconds(60);
                            Audit(cid, by, "chat:" + name, target, tname, lineCopy, ok2, o2);
                            ReplyU(peer, cid, ui, ok2, tname + ": " + o2, ok2);
                            if (ui) { nextSnap = DateTime.UtcNow.AddSeconds(2); pendingUi[cid] = peer; }
                        });
                        return;
                    }
                case "prisoners":
                    output = Run("coop.debug.mobile_party.add_prisoners", new List<string> { heroName }, out ok); break;
                case "prisonersclear":
                    output = Run("coop.debug.mobile_party.remove_prisoners", new List<string> { heroName }, out ok); break;
                case "give":
                    {
                        var st = FindIn("world.json", "settlements", rest);
                        if (st == null) { Reply(peer, cid, ui, false, "مش لاقي مدينة اسمها \"" + rest + "\""); return; }
                        if (Mj.S(st, "type", "") == "village") { Reply(peer, cid, ui, false, "القرية بتتبع المدينة أو القلعة بتاعتها (" + Mj.S(st, "bound", "") + "). ادّيه دي، والقرية هتيجي معاها."); return; }
                        output = Run("coop.debug.settlements.set_owner_clan", new List<string> { Mj.S(st, "id", ""), heroId }, out ok) + " ← " + Mj.S(st, "name", "");
                        break;
                    }
                case "take":
                    {
                        var st = FindIn("world.json", "settlements", arg1);
                        var k = FindIn("world.json", "kingdoms", after1);
                        if (st == null) { Reply(peer, cid, ui, false, "مش لاقي المدينة \"" + arg1 + "\""); return; }
                        if (Mj.S(st, "type", "") == "village") { Reply(peer, cid, ui, false, "القرية بتتبع المدينة أو القلعة بتاعتها (" + Mj.S(st, "bound", "") + ")."); return; }
                        if (k == null || Mj.S(k, "leaderId", "").Length == 0) { Reply(peer, cid, ui, false, "مش لاقي حاكم المملكة \"" + after1 + "\""); return; }
                        output = Run("coop.debug.settlements.set_owner_clan", new List<string> { Mj.S(st, "id", ""), Mj.S(k, "leaderId", "") }, out ok) + "  " + Mj.S(st, "name", "") + " ← " + Mj.S(k, "name", "");
                        break;
                    }
                case "kingdom":
                case "vassal":
                    {
                        var k = FindIn("world.json", "kingdoms", rest);
                        if (k == null) { Reply(peer, cid, ui, false, "مش لاقي مملكة اسمها \"" + rest + "\""); return; }
                        output = Run(name == "kingdom" ? "coop.debug.kingdom.force_player_join_kingdom" : "coop.debug.kingdom.force_player_vassalage", new List<string> { target, Mj.S(k, "id", "") }, out ok) + " ← " + Mj.S(k, "name", "");
                        break;
                    }
                case "leave":
                    {
                        // modes:  normal = plain leave (fiefs go back) | keep = leaves with the fiefs, peace with EVERY kingdom
                        //         war = leaves with the fiefs, war only with the old kingdom (peace with all the others)
                        //         allwar = leaves with the fiefs, war with every kingdom | bare = leaves with nothing: no kingdom, no wars, no fiefs
                        var mode = arg1.ToLowerInvariant(); var clanId = Mj.S(p, "clanId", ""); var kid = Mj.S(p, "kingdomId", "");
                        if (kid.Length == 0) { Reply(peer, cid, ui, false, PName(p) + " مش في مملكة."); return; }
                        if (mode == "war" || mode == "keep" || mode == "allwar" || mode == "bare")
                        {
                            try { WriteWorld(); } catch { }
                            var kings = new List<Dictionary<string, object>>();
                            try { var wr = ReadJson(Path.Combine(StateDir, "world.json")); object ko; if (wr.TryGetValue("kingdoms", out ko) && ko is IEnumerable) kings = ((IEnumerable)ko).OfType<Dictionary<string, object>>().ToList(); } catch { }
                            string leaderId = ""; foreach (var kk in kings) if (Mj.S(kk, "id", "") == kid) leaderId = Mj.S(kk, "leaderId", "");
                            var clanName = Mj.S(p, "clan", "");
                            // fiefs of the clan (read before the clan leaves)
                            var fiefs = new List<Dictionary<string, object>>();
                            if (mode == "bare" && clanName.Length > 0)
                                try { var wr = ReadJson(Path.Combine(StateDir, "world.json")); object so; if (wr.TryGetValue("settlements", out so) && so is IEnumerable) fiefs = ((IEnumerable)so).OfType<Dictionary<string, object>>().Where(x => Mj.S(x, "owner", "") == clanName).ToList(); } catch { }
                            output = Run("coop.debug.clan.leave_kingdom", new List<string> { clanId, mode == "bare" ? "normal" : "rebellion", target }, out ok);
                            if (!ok && mode != "bare" && output.IndexOf("mercenary", StringComparison.OrdinalIgnoreCase) >= 0)
                            {   // a mercenary clan has no fiefs to keep: plain leave
                                output = Run("coop.debug.clan.leave_kingdom", new List<string> { clanId, "normal", target }, out ok); mode = "normal";
                            }
                            else if (ok)
                            {
                                int handed = 0;
                                if (mode == "bare" && leaderId.Length > 0)
                                    foreach (var f in fiefs)
                                    { bool okf; Run("coop.debug.settlements.set_owner_clan", new List<string> { Mj.S(f, "id", ""), leaderId }, out okf); if (okf) handed++; }
                                // the game hands the old kingdom's wars to the clan when it leaves; Coop replicates stance changes a moment later.
                                // So the wanted relations are checked against the live campaign several times and fixed until they hold.
                                LeaveFix(peer, cid, ui, by, target, tname, clanId, kid, mode, 0);
                                if (mode == "keep") output += "\nبإقطاعاته. بظبط السلام مع كل الممالك وبتأكد منه خلال ثواني…";
                                else if (mode == "war") output += "\nبإقطاعاته. حرب مع مملكته القديمة بس — بظبط السلام مع الباقي وبتأكد…";
                                else if (mode == "allwar") output += "\nبإقطاعاته. بعلن الحرب على كل الممالك وبتأكد…";
                                else if (mode == "bare") output += "\nسلّم " + handed + " إقطاعية من " + fiefs.Count + " لحاكم المملكة القديمة. بظبط السلام مع الكل…";
                            }
                        }
                        else output = Run("coop.debug.clan.leave_kingdom", new List<string> { clanId, "normal", target }, out ok);
                        break;
                    }
                case "restart":
                    {
                        double m; if (!double.TryParse(tk[0], NumberStyles.Float, CultureInfo.InvariantCulture, out m) || m < 1) { Reply(peer, cid, ui, false, "اكتب عدد الدقايق (1 أو أكتر)"); return; }
                        Broadcast("[إعلان من " + by + "]  السيرفر هيقفل للصيانة بعد " + Inv(m) + " دقيقة. اللعبة هتتحفظ.");
                        output = Run("coop.server.shutdown", new List<string> { Inv(m * 60) }, out ok); break;
                    }
                case "cmd":
                    output = Run(tk[0], tk.Skip(1).ToList(), out ok); break;
                case "kwar":
                case "kpeace":
                    {
                        var k1 = FindIn("world.json", "kingdoms", tk[0]); var k2 = FindIn("world.json", "kingdoms", string.Join(" ", tk.Skip(1)));
                        if (k1 == null || k2 == null) { Reply(peer, cid, ui, false, "مش لاقي المملكة \"" + (k1 == null ? tk[0] : string.Join(" ", tk.Skip(1))) + "\""); return; }
                        if (Mj.S(k1, "id", "") == Mj.S(k2, "id", "")) { Reply(peer, cid, ui, false, "اختار مملكتين مختلفين"); return; }
                        var a = FacById(Mj.S(k1, "id", "")); var b = FacById(Mj.S(k2, "id", ""));
                        if (a == null || b == null) { Reply(peer, cid, ui, false, "مش لاقي الممالك في الحملة"); return; }
                        bool want = name == "kwar"; string err2;
                        ok = SetWar(a, b, want, Mj.S(k1, "id", ""), Mj.S(k2, "id", ""), "", out err2);
                        var pairName = Mj.S(k1, "name", "") + " و " + Mj.S(k2, "name", "");
                        if (!ok)
                        {   // Coop may apply the stance change a moment later: check again before calling it a failure
                            var pr0 = peer; var ui0 = ui; var e0 = err2;
                            Later(3, () => { bool now = AtWar(a, b) == want; ReplyU(Peer(cid) ?? pr0, cid, ui0, now, now ? (want ? "⚔ حرب بين " : "☮ سلام بين ") + pairName : "مقدرتش أغيّر العلاقة بين " + pairName + (e0.Length > 0 ? ": " + Cut(e0, 120) : ""), false); });
                            Audit(cid, by, "chat:" + name, "", "", line, true, "pending");
                            return;
                        }
                        output = (want ? "⚔ حرب بين " : "☮ سلام بين ") + pairName;
                        undoLine = (want ? "kpeace " : "kwar ") + "\"" + Mj.S(k1, "name", "") + "\" \"" + Mj.S(k2, "name", "") + "\""; undoLabel = (want ? "سلام" : "حرب") + " بين " + Mj.S(k1, "name", "") + " و " + Mj.S(k2, "name", "");
                        break;
                    }
                case "relations":
                    {
                        var c = FacById(Mj.S(p, "clanId", "")); if (c == null) { Reply(peer, cid, ui, false, "مش لاقي عشيرته"); return; }
                        var wars = Enemies(c).Select(x => Str(Get(x, "Name"))).ToList();
                        Reply(peer, cid, ui, true, tname + (wars.Count == 0 ? ": مش في حرب مع حد" : ": في حرب مع " + string.Join("، ", wars)));
                        return;
                    }
                case "starter":
                    {
                        var h = FindHero(heroId, null); var cur = Num(Get(h, "Gold"));
                        bool ok1, ok2; Run("coop.debug.hero.set_gold_state", new List<string> { heroId, Inv(cur + 5000) }, out ok1);
                        Run("coop.debug.mobile_party.add_troops", new List<string> { heroName }, out ok2);
                        var pp = p;
                        OnMain(() => { bool ok3; ItemSet(pp, "grain", 15, out ok3); });
                        ok = ok1 || ok2;
                        output = (ok1 ? "✓ +5,000 دينار" : "✗ الفلوس") + "  •  " + (ok2 ? "✓ جنود" : "✗ الجنود") + "  •  أكل (15 قمح)";
                        undoLine = "gold " + target + " " + Inv(cur); undoLabel = "فلوس " + tname + " ترجع " + Fmt(cur);
                        break;
                    }
                case "note":
                    AddNote(target, by, rest); output = "✓ اتسجلت الملاحظة"; break;
                case "undo":
                    {
                        string[] u; if (!lastUndo.TryGetValue(cid, out u)) { Reply(peer, cid, ui, false, "مفيش أمر أرجّعه"); return; }
                        lastUndo.Remove(cid);
                        Audit(cid, by, "undo", "", "", u[1], true, u[0]);
                        ChatCommand(peer, cid, u[0], ui);   // runs (and checks the permission of) the inverse command
                        return;
                    }
                case "banner":
                    {
                        int n = BannerAll(rest, by);
                        output = "✓ البانر ظهر لـ " + n + " لاعب"; break;
                    }
                case "adminsay":
                    {
                        int n = 0;
                        foreach (var x in OnlineSorted())
                        {
                            var xc = Mj.S(x, "controllerId", ""); if (!admins.ContainsKey(xc)) continue;
                            var pr = Peer(xc); if (pr == null) continue; Say(pr, xc, "[للإدارة — " + by + "]  " + rest); n++;
                        }
                        output = "✓ وصلت لـ " + n + " إداري"; break;
                    }
                case "sched":
                    {
                        double after, every;
                        if (!double.TryParse(tk[0], NumberStyles.Float, CultureInfo.InvariantCulture, out after) || after < 0 || !double.TryParse(tk[1], NumberStyles.Float, CultureInfo.InvariantCulture, out every) || every < 0)
                        { Reply(peer, cid, ui, false, "الاستخدام: " + cmd.Usage); return; }
                        var mode = tk[2].ToLowerInvariant(); if (mode != "chat" && mode != "banner" && mode != "admins") { Reply(peer, cid, ui, false, "الطريقة: chat أو banner أو admins"); return; }
                        if (every > 0 && every < 5) { Reply(peer, cid, ui, false, "أقل تكرار كل 5 دقايق"); return; }
                        var text = string.Join(" ", tk.Skip(3));
                        var id = AddSchedule(after, every, mode, text, by);
                        output = "✓ إعلان مجدول رقم " + id + (after > 0 ? " — بعد " + Inv(after) + " دقيقة" : " — دلوقتي") + (every > 0 ? " ويتكرر كل " + Inv(every) + " دقيقة" : "");
                        break;
                    }
                case "unsched":
                    output = RemoveSchedule(tk[0]) ? "✓ اتلغى الإعلان المجدول " + tk[0] : "مفيش إعلان مجدول بالرقم ده"; ok = output.StartsWith("✓"); break;
                case "banid":
                    {
                        var id = tk[0].Trim(); ulong tmp;
                        if (id.Length < 15 || !ulong.TryParse(id, out tmp)) { Reply(peer, cid, ui, false, "رقم Steam64 مش صحيح (17 رقم)"); return; }
                        target = id; tname = KnownName(id);
                        var why = string.Join(" ", tk.Skip(1));
                        output = ServerBan(id, tname, why, by, 0);
                        if (Peer(id) != null) { bool okk; Kick(id, why.Length > 0 ? why : "اتحظرت بواسطة الإدارة", out okk); }
                        break;
                    }
                case "save":
                    output = Run("coop.debug.save.force_autosave", new List<string>(), out ok); if (ok) output = "✓ الحملة اتحفظت  " + output; break;
                default:
                    return;
            }
            if (target.Length > 0) ignoreUntil[target] = DateTime.UtcNow.AddSeconds(60);
            Audit(cid, by, "chat:" + name, target, tname, line, ok, output);
            if (ok && undoLine != null) SetUndo(cid, undoLine, undoLabel);
            ReplyU(peer, cid, ui, ok, (tname.Length > 0 && name != "banid" ? tname + ": " : "") + output, ok && undoLine != null);
            if (ui) { nextSnap = DateTime.UtcNow.AddSeconds(2); pendingUi[cid] = peer; }
        }

        // ---------------------------------------------------------------- warnings / mutes
        static Dictionary<string, object> WarnFile() { return ReadJson(Path.Combine(Root, "warnings.json")); }
        static List<object> Warnings(string cid)
        {
            object o; var d = WarnFile();
            return d.TryGetValue(cid ?? "", out o) && o is IEnumerable && !(o is string) ? ((IEnumerable)o).Cast<object>().ToList() : new List<object>();
        }
        static int AddWarning(string cid, string by, string reason)
        {
            var d = WarnFile(); var l = Warnings(cid);
            var w = new Dictionary<string, object>(); w["time"] = Iso(DateTime.Now); w["by"] = by; w["reason"] = reason;
            l.Add(w); d[cid] = l; WriteJson(Path.Combine(Root, "warnings.json"), d);
