            DateTime mu; d["muted"] = IsMuted(cid, out mu) ? (mu.Year > 9000 ? "دايم" : mu.ToString("HH:mm", CultureInfo.InvariantCulture)) : "";
            d["isAdmin"] = admins.ContainsKey(cid);
            var nl = Notes(cid); d["notes"] = nl.Count;
            if (nl.Count > 0) { var last = nl[nl.Count - 1] as Dictionary<string, object>; if (last != null) d["note"] = Mj.S(last, "text", "") + "  — " + Mj.S(last, "by", "") + " " + Mj.S(last, "time", ""); }
            Online on; if (online.TryGetValue(cid, out on)) d["onlineMin"] = Math.Round((DateTime.UtcNow - on.Since).TotalMinutes);
