        // ---- jobs that run a few seconds later on the game thread
        static readonly List<KeyValuePair<DateTime, Action>> later = new List<KeyValuePair<DateTime, Action>>();
        static void Later(double seconds, Action a) { lock (later) later.Add(new KeyValuePair<DateTime, Action>(DateTime.UtcNow.AddSeconds(seconds), a)); }
        static void RunLater()
        {
            List<Action> due = null; var now = DateTime.UtcNow;
            lock (later)
            {
                if (later.Count == 0) return;
                for (int i = later.Count - 1; i >= 0; i--)
                    if (later[i].Key <= now) { if (due == null) due = new List<Action>(); due.Add(later[i].Value); later.RemoveAt(i); }
            }
            if (due != null) foreach (var a in due) { try { a(); } catch (Exception e) { Log.W("AdminHost later-job: " + (e.InnerException ?? e)); } }
        }

        // ---- factions in the live campaign (all by reflection)
        static Type tClan, tKingdom, tFM, tPeace, tWar, tIFaction;
        static void FacTypes()
        {
            if (tClan != null) return;
            tClan = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Clan"); tKingdom = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Kingdom");
            tFM = AccessTools.TypeByName("TaleWorlds.CampaignSystem.FactionManager"); tIFaction = AccessTools.TypeByName("TaleWorlds.CampaignSystem.IFaction");
            tPeace = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Actions.MakePeaceAction"); tWar = AccessTools.TypeByName("TaleWorlds.CampaignSystem.Actions.DeclareWarAction");
        }
        static object FacById(string id)
        {
            FacTypes(); if (string.IsNullOrEmpty(id)) return null;
            foreach (var t in new[] { tKingdom, tClan })
            {
                var all = Get(t, "All") as IEnumerable; if (all == null) continue;
                foreach (var f in all) if (Str(Get(f, "StringId")) == id) return f;
            }
            return null;
        }
        static List<object> LiveKingdoms()
        {
            FacTypes(); var r = new List<object>(); var all = Get(tKingdom, "All") as IEnumerable;
            if (all != null) foreach (var k in all) { var el = Get(k, "IsEliminated"); if (!(el is bool && (bool)el)) r.Add(k); }
            return r;
        }
        static bool B0(object o, string n) { var v = Get(o, n); return v is bool && (bool)v; }
        // independent clans the player's clan could be at war with (no bandits, no clans inside a kingdom: their kingdom covers them)
        static List<object> FreeClans(object self)
        {
            FacTypes(); var r = new List<object>(); var all = Get(tClan, "All") as IEnumerable;
            if (all != null) foreach (var c in all) if (c != self && Get(c, "Kingdom") == null && !B0(c, "IsBanditFaction") && !B0(c, "IsEliminated")) r.Add(c);
            return r;
        }
        static MethodInfo atWarM;
        static bool AtWar(object a, object b)
        {
            FacTypes();
            if (atWarM == null) atWarM = tFM.GetMethod("IsAtWarAgainstFaction", BindingFlags.Static | BindingFlags.Public);
            try { var v = atWarM.Invoke(null, new[] { a, b }); return v is bool && (bool)v; } catch { return false; }
        }
        static List<object> Enemies(object clan)
        {
            var r = new List<object>();
            foreach (var k in LiveKingdoms()) if (AtWar(clan, k)) r.Add(k);
            foreach (var c in FreeClans(clan)) if (AtWar(clan, c)) r.Add(c);
            return r;
        }
        // war on/off between two factions: Coop's own command first (it replicates to every player), the game's action if that refused
        static bool SetWar(object a, object b, bool war, string aId, string bId, string actor, out string err)
        {
            err = "";
            if (AtWar(a, b) == war) return true;
            bool ok;
            var args = new List<string> { aId, bId }; if (actor.Length > 0) args.Add(actor);
            string r;
            if (war)
            {
                r = "";
                foreach (var cause in new[] { "Default", "CausedByKingdomDecision", "CausedByPlayerHostility" })
                {
                    var a2 = new List<string> { aId, bId, cause }; if (actor.Length > 0) a2.Add(actor);
                    r = Run("coop.debug.kingdom.declare_war", a2, out ok); if (ok) break;
                }
            }
            else r = Run("coop.debug.kingdom.make_peace", args, out ok);
            if (AtWar(a, b) == war) return true;
            try
            {
                if (war) tWar.GetMethod("ApplyByDefault", BindingFlags.Static | BindingFlags.Public).Invoke(null, new[] { a, b });
                else tPeace.GetMethods(BindingFlags.Static | BindingFlags.Public).First(m => m.Name == "Apply" && m.GetParameters().Length == 2).Invoke(null, new[] { a, b });
            }
            catch (Exception e) { err = (e.InnerException ?? e).Message; }
            if (AtWar(a, b) == war) return true;
            if (err.Length == 0) err = r;
            return false;
        }

        // keep = peace with everybody | war = war with the old kingdom only | allwar = war with every kingdom | bare = peace with everybody
        // pass 0 runs right away, then again after 3 s, 10 s and 30 s (Coop replicates the leave and its wars a moment later);
        // the admin gets the real end state.
        static readonly double[] LeavePasses = { 0, 3, 10, 30 };
        static void LeaveFix(object peer, string cid, bool ui, string by, string target, string tname, string clanId, string oldKid, string mode, int pass)
        {
            Action job = () =>
            {
                var clan = FacById(clanId); if (clan == null) { Log.W("LeaveFix: clan " + clanId + " not found"); return; }
                int fixedN = 0; var failed = new List<string>();
                foreach (var k in LiveKingdoms())
                {
                    var kid = Str(Get(k, "StringId"));
                    bool want = mode == "allwar" || (mode == "war" && kid == oldKid);
                    if (AtWar(clan, k) == want) continue;
                    string err; if (SetWar(clan, k, want, clanId, kid, target, out err)) fixedN++; else failed.Add(Str(Get(k, "Name")) + (err.Length > 0 ? " (" + Cut(err, 60) + ")" : ""));
                }
                foreach (var c in FreeClans(clan))
                {
                    if (!AtWar(clan, c) || mode == "allwar") continue;   // only peace with independent clans; allwar is about kingdoms
                    string err; if (SetWar(clan, c, false, clanId, Str(Get(c, "StringId")), target, out err)) fixedN++; else failed.Add(Str(Get(c, "Name")));
                }
                if (fixedN > 0 || failed.Count > 0) Log.W("LeaveFix " + mode + " pass " + pass + " " + tname + ": fixed " + fixedN + ", failed " + failed.Count);
                if (pass + 1 < LeavePasses.Length) { LeaveFix(peer, cid, ui, by, target, tname, clanId, oldKid, mode, pass + 1); return; }
                // final report: the relations as they are now
                var wars = Enemies(clan).Select(x => Str(Get(x, "Name"))).ToList();
                bool good = failed.Count == 0;
                var txt = tname + ": " + (wars.Count == 0 ? "✓ خرج ومش في حرب مع أي حد" : (good ? "✓ " : "⚠ ") + "خرج وفي حرب مع: " + string.Join("، ", wars)) + (failed.Count > 0 ? "\nمقدرتش أظبط: " + string.Join("، ", failed) : "");
                Audit(cid, by, "leave-fix:" + mode, target, tname, "", good, txt);
                var pr = Peer(cid) ?? peer;
                if (ui) { var d = new Dictionary<string, object>(); d["ok"] = good; d["text"] = txt; UiSend(pr, cid, "result", d); pendingUi[cid] = pr; nextSnap = DateTime.UtcNow.AddSeconds(1); }
                else Say(pr, cid, txt);
            };
            var delay = LeavePasses[pass] - (pass == 0 ? 0 : LeavePasses[pass - 1]);
            if (pass == 0) OnMain(job); else Later(delay, job);
        }
        static string Cut(string s, int n) { s = s ?? ""; return s.Length > n ? s.Substring(0, n) + "…" : s; }

        // ---- notes
        static List<object> Notes(string cid)
        {
            object o; var d = ReadJson(Path.Combine(Root, "notes.json"));
            return d.TryGetValue(cid ?? "", out o) && o is IEnumerable && !(o is string) ? ((IEnumerable)o).Cast<object>().ToList() : new List<object>();
        }
        static void AddNote(string cid, string by, string text)
        {
            var f = Path.Combine(Root, "notes.json"); var d = ReadJson(f);
            var l = Notes(cid); var n = new Dictionary<string, object>(); n["by"] = by; n["text"] = text; n["time"] = DateTime.Now.ToString("yyyy-MM-dd HH:mm", CultureInfo.InvariantCulture);
            l.Add(n); while (l.Count > 30) l.RemoveAt(0); d[cid] = l; WriteJson(f, d);
        }

        // ---- banner in the middle of every player's screen (their Aurelion client shows it)
        static int BannerAll(string text, string by)
        {
            int n = 0; var d = new Dictionary<string, object>(); d["text"] = text; d["by"] = by;
            foreach (var x in OnlineSorted())
            {
                var xc = Mj.S(x, "controllerId", ""); var pr = Peer(xc); if (pr == null) continue;
                UiSend(pr, xc, "banner", d); Say(pr, xc, "[إعلان من الإدارة]  " + text); n++;
            }
            return n;
        }

        // ---- scheduled / repeating announcements (schedule.json survives restarts)
        static List<Dictionary<string, object>> Schedules()
        {
            object o; var d = ReadJson(Path.Combine(Root, "schedule.json"));
            return d.TryGetValue("items", out o) && o is IEnumerable ? ((IEnumerable)o).OfType<Dictionary<string, object>>().ToList() : new List<Dictionary<string, object>>();
        }
        static void SaveSchedules(List<Dictionary<string, object>> l) { var d = new Dictionary<string, object>(); d["items"] = l.Cast<object>().ToList(); WriteJson(Path.Combine(Root, "schedule.json"), d); }
        static string AddSchedule(double after, double every, string mode, string text, string by)
        {
            var l = Schedules(); int id = 1; foreach (var x in l) { int v; if (int.TryParse(Mj.S(x, "id", "0"), out v) && v >= id) id = v + 1; }
            var d = new Dictionary<string, object>();
            d["id"] = id.ToString(CultureInfo.InvariantCulture); d["next"] = Iso(DateTime.Now.AddMinutes(after)); d["every"] = every; d["mode"] = mode; d["text"] = text; d["by"] = by; d["created"] = Iso(DateTime.Now);
            l.Add(d); SaveSchedules(l);
            if (after <= 0) ProcessSchedules();
            return d["id"].ToString();
        }
        static bool RemoveSchedule(string id)
        {
            var l = Schedules(); var n = l.RemoveAll(x => Mj.S(x, "id", "") == id); if (n > 0) SaveSchedules(l); return n > 0;
        }
        static void ProcessSchedules()
        {
            var l = Schedules(); if (l.Count == 0) return; bool dirty = false;
            foreach (var x in l.ToList())
            {
                DateTime next; if (!DateTime.TryParseExact(Mj.S(x, "next", ""), "yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture, DateTimeStyles.None, out next)) { l.Remove(x); dirty = true; continue; }
                if (next > DateTime.Now) continue;
                var text = Mj.S(x, "text", ""); var mode = Mj.S(x, "mode", "chat"); var by = Mj.S(x, "by", "");
                if (mode == "banner") BannerAll(text, by);
                else if (mode == "admins") { foreach (var p in OnlineSorted()) { var xc = Mj.S(p, "controllerId", ""); if (admins.ContainsKey(xc)) { var pr = Peer(xc); if (pr != null) Say(pr, xc, "[للإدارة — " + by + "]  " + text); } } }
                else Broadcast("[إعلان من " + by + "]  " + text);
                Audit("", by, "sched", "", "", mode, true, text);
                var every = Mj.N(x, "every", 0);
                if (every > 0) { var nx = next; while (nx <= DateTime.Now) nx = nx.AddMinutes(every); x["next"] = Iso(nx); } else l.Remove(x);
                dirty = true;
            }
            if (dirty) SaveSchedules(l);
        }

        // ---- the menu's alerts tab
        static void UiAlerts(object peer, string cid)
        {
            var list = new List<object>();
            try
            {
                var f = Path.Combine(Root, "alerts.jsonl");
                if (File.Exists(f))
                    foreach (var l in File.ReadAllLines(f, Encoding.UTF8).Reverse().Where(x => x.Trim().Length > 0).Take(40))
                    { var h = Mj.Parse(l) as Dictionary<string, object>; if (h != null) list.Add(h); }
            }
            catch { }
            var rules = new List<object>();
            Action<string, string, bool> rule = (n, lim, on) => { var r = new Dictionary<string, object>(); r["name"] = n; r["limit"] = lim; r["on"] = on; rules.Add(r); };
            rule("فلوس غريبة", "أكتر من " + Fmt(cfg.GoldPerMin) + " دينار في الدقيقة", cfg.CheatsEnabled);
            rule("شهرة غريبة", "أكتر من " + Fmt(cfg.RenownPerMin) + " في الدقيقة", cfg.CheatsEnabled);
            rule("جنود غريبة", "أكتر من " + Fmt(cfg.TroopsPerMin) + " جندي في الدقيقة", cfg.CheatsEnabled);
            rule("مهارات غريبة", "أكتر من " + Fmt(cfg.SkillsPerMin) + " نقطة في الدقيقة", cfg.CheatsEnabled);
            rule("مدن غريبة", "أكتر من " + Fmt(cfg.SettlementsPerMin) + " مدينة في الدقيقة", cfg.CheatsEnabled);
            rule("سرعة / نقل غريب", "الجيش اتحرك أكتر من " + Fmt(cfg.MapJump) + " وحدة في 3 ثواني", cfg.CheatsEnabled && cfg.MapJump > 0);
            rule("نفس الـ IP", "أكتر من لاعب من نفس الجهاز", cfg.SameIpAlert);
            rule("كود أدمن غلط", "3 محاولات غلط ← قفل 10 دقايق", true);
            var d = new Dictionary<string, object>(); d["alerts"] = list; d["rules"] = rules;
            UiSend(peer, cid, "alerts", d);
        }

        // ---- the menu's server tab
        static void UiHealth(object peer, string cid)
        {
            var d = new Dictionary<string, object>();
            d["online"] = OnlineSorted().Count; d["known"] = known == null ? 0 : known.Count;
            d["uptimeMin"] = Math.Round((DateTime.UtcNow - serverSince).TotalMinutes);
            string date = ""; try { date = Str(Get(AccessTools.TypeByName("TaleWorlds.CampaignSystem.CampaignTime"), "Now")); } catch { }
            d["date"] = date; d["mode"] = CampaignMode(); d["frameMs"] = Math.Round(frameAvg, 1);
            d["catchUp"] = CatchUpPaused(); d["alwaysTime"] = cfg.AlwaysTime; d["timeFixes"] = timeFixes; d["timeBlocked"] = timeBlocked; d["version"] = Version;
            int ban = 0, temp = 0; try { object lo; var br = ReadJson(Path.Combine(Root, "bans.json")); if (br.TryGetValue("bans", out lo) && lo is IEnumerable) foreach (var b in ((IEnumerable)lo).OfType<Dictionary<string, object>>()) { ban++; if (Mj.S(b, "until", "").Length > 0) temp++; } } catch { }
            d["bans"] = ban; d["tempBans"] = temp;
            int al = 0; try { var f = Path.Combine(Root, "alerts.jsonl"); if (File.Exists(f)) { var today = DateTime.Now.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture); al = File.ReadAllLines(f, Encoding.UTF8).Count(x => x.Contains("\"" + today)); } } catch { }
            d["alertsToday"] = al;
            try
            {
                var dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments), "Mount and Blade II Bannerlord", "Game Saves");
                if (Directory.Exists(dir))
                {
                    var f = new DirectoryInfo(dir).GetFiles("*.sav", SearchOption.AllDirectories).OrderByDescending(x => x.LastWriteTime).FirstOrDefault();
                    if (f != null) { d["lastSave"] = f.LastWriteTime.ToString("HH:mm", CultureInfo.InvariantCulture); d["lastSaveMin"] = Math.Round((DateTime.Now - f.LastWriteTime).TotalMinutes); d["lastSaveName"] = Path.GetFileNameWithoutExtension(f.Name); }
                }
            }
            catch { }
            var adm = new List<object>(); var on = new HashSet<string>(OnlineSorted().Select(x => Mj.S(x, "controllerId", "")));
            foreach (var kv in admins)
            {
                var a = new Dictionary<string, object>(); a["name"] = Mj.S(kv.Value, "name", KnownName(kv.Key)); a["level"] = Mj.S(kv.Value, "level", "observer");
                a["online"] = on.Contains(kv.Key); a["perms"] = PermsOf(kv.Key).Count; adm.Add(a);
            }
            d["admins"] = adm;
            d["schedules"] = Schedules().Cast<object>().ToList();
            UiSend(peer, cid, "health", d);
        }

        static void FlushPendingUi()
        {
            if (pendingUi.Count == 0) return;
            foreach (var kv in pendingUi.ToList()) { var pr = Peer(kv.Key); if (pr != null) UiPlayers(pr, kv.Key); }
            pendingUi.Clear();
        }

        // ------------------------------------------------------------------ audit log
        static void Audit(string by, string byName, string action, string target, string targetName, string reason, bool ok, string output, string id = "", Dictionary<string, object> cmd = null)
        {
            var d = new Dictionary<string, object>();
            d["time"] = Iso(DateTime.Now); d["id"] = id; d["by"] = by; d["byName"] = byName; d["action"] = action;
            d["target"] = target; d["targetName"] = targetName; d["reason"] = reason; d["ok"] = ok; d["output"] = output ?? "";
            if (cmd != null) { object a; if (cmd.TryGetValue("args", out a)) d["args"] = a; object l; if (cmd.TryGetValue("label", out l)) d["label"] = l; }
            AppendLine(Path.Combine(Root, "audit.jsonl"), d);
        }

        // ------------------------------------------------------------------ small helpers
        public static object Get(object o, string name)
        {
            if (o == null) return null;
            var t = o as Type ?? o.GetType(); var inst = o is Type ? null : o;
            for (var x = t; x != null; x = x.BaseType)
            {
                var p = x.GetProperty(name, All | BindingFlags.DeclaredOnly);
                if (p != null && p.GetIndexParameters().Length == 0) { try { return p.GetValue(inst, null); } catch { return null; } }
                var f = x.GetField(name, All | BindingFlags.DeclaredOnly);
                if (f != null) { try { return f.GetValue(inst); } catch { return null; } }
            }
            return null;
        }
        static string Str(object o) { return o == null ? "" : Convert.ToString(o, CultureInfo.InvariantCulture); }
        static double Num(object o) { try { return o == null ? 0 : Convert.ToDouble(o, CultureInfo.InvariantCulture); } catch { return 0; } }
        static bool IsSteam64(string s) { ulong v; return s != null && s.Length == 17 && s.StartsWith("7656") && ulong.TryParse(s, out v); }
        static string Iso(DateTime t) { return t.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture); }

        static Dictionary<string, object> ReadJson(string path)
        {
            try { if (File.Exists(path)) return Mj.Parse(File.ReadAllText(path, Encoding.UTF8)) as Dictionary<string, object> ?? new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase); }
            catch (Exception e) { Log.W("read " + path + ": " + e.Message); }
            return new Dictionary<string, object>(StringComparer.OrdinalIgnoreCase);
        }
        static void WriteJson(string path, object o)
        {
            try
            {
                Directory.CreateDirectory(Path.GetDirectoryName(path));
                var tmp = path + ".tmp";
                File.WriteAllText(tmp, Jw.Write(o), new UTF8Encoding(false));
                if (File.Exists(path)) File.Replace(tmp, path, null); else File.Move(tmp, path);
            }
            catch (Exception e) { Log.W("write " + path + ": " + e.Message); }
        }
        static void AppendLine(string path, object o)
        {
            try { Directory.CreateDirectory(Path.GetDirectoryName(path)); File.AppendAllText(path, Jw.Write(o) + "\n", new UTF8Encoding(false)); }
            catch (Exception e) { Log.W("append " + path + ": " + e.Message); }
        }
    }

    // ---------------------------------------------------------------- tiny JSON writer (one line)
    public static class Jw
    {
        public static string Write(object o) { var sb = new StringBuilder(); W(sb, o); return sb.ToString(); }
        static void W(StringBuilder sb, object o)
        {
            if (o == null) { sb.Append("null"); return; }
            if (o is string) { S(sb, (string)o); return; }
            if (o is bool) { sb.Append((bool)o ? "true" : "false"); return; }
            if (o is IDictionary<string, object>)
            {
                sb.Append('{'); bool first = true;
                foreach (var kv in (IDictionary<string, object>)o) { if (!first) sb.Append(','); first = false; S(sb, kv.Key); sb.Append(':'); W(sb, kv.Value); }
                sb.Append('}'); return;
            }
            if (o is IEnumerable)
            {
                sb.Append('['); bool first = true;
                foreach (var x in (IEnumerable)o) { if (!first) sb.Append(','); first = false; W(sb, x); }
                sb.Append(']'); return;
            }
            if (o is double || o is float || o is decimal) { var d = Convert.ToDouble(o); sb.Append(double.IsNaN(d) || double.IsInfinity(d) ? "0" : d.ToString("0.######", CultureInfo.InvariantCulture)); return; }
            if (o.GetType().IsPrimitive) { sb.Append(Convert.ToString(o, CultureInfo.InvariantCulture)); return; }
            S(sb, Convert.ToString(o, CultureInfo.InvariantCulture));
        }
        static void S(StringBuilder sb, string s)
        {
            sb.Append('"');
            foreach (var c in s)
            {
                if (c == '"') sb.Append("\\\""); else if (c == '\\') sb.Append("\\\\");
                else if (c == '\n') sb.Append("\\n"); else if (c == '\r') sb.Append("\\r"); else if (c == '\t') sb.Append("\\t");
                else if (c < 0x20) sb.Append("\\u").Append(((int)c).ToString("x4"));
                else sb.Append(c);
            }
            sb.Append('"');
        }
    }
